class RController {
  /**
   * 检查 R 环境是否可用
   */
  async checkR(): Promise<{ available: boolean; message: string }> {
    try {
      const available = await rService.checkRAvailable();

      if (available) {
        return { 
          available: true, 
          message: 'R environment is ready' 
        };
      } else {
        return { 
          available: false, 
          message: 'R not found. Please install R from https://cran.r-project.org/ and ensure Rscript is in your PATH' 
        };
      }
    } catch (err: any) {
      return { 
        available: false, 
        message: `Error checking R: ${err.message}` 
      };
    }
  }

  /**
   * 配置 R 路径（用于便携版 R）
   */
  async setRPath(rPath: string): Promise<{ success: boolean; message: string }> {
    try {
      rService.setRPath(rPath);
      return { 
        success: true, 
        message: 'R path configured successfully' 
      };
    } catch (err: any) {
      return { 
        success: false, 
        message: `Failed to configure R path: ${err.message}` 
      };
    }
  }

  /**
   * 执行 PERMANOVA 分析
   */
  async runPERMANOVA(params: {
    distanceMatrix: number[][];
    formula: string;
    permutations?: number;
    strata?: string[];
  }): Promise<any> {
    logger.info('[RController] Running PERMANOVA with params:', params);

    const result = await rService.runScript({
      scriptName: 'permanova.R',
      params,
      timeout: 600000 // 10 分钟
    });

    if (!result.success) {
      throw new Error(result.error || 'PERMANOVA execution failed');
    }

    return result.data;
  }

  /**
