if (require("LDM", character.only = TRUE, quietly = TRUE)) {
  ldm_version <- as.character(packageVersion("LDM"))
  cat("   ✅ LDM 已安装，版本:", ldm_version, "\n")

  # 检查包路径
  ldm_path <- find.package("LDM")
  cat("   安装路径:", ldm_path, "\n")

  # 检查依赖
  cat("\n3. 检查 LDM 依赖:\n")
  deps <- unclass(tools::package_dependencies("LDM", installed.packages(), which = c("Depends", "Imports", "LinkingTo")))[[1]]
  for (dep in deps) {
    if (require(dep, character.only = TRUE, quietly = TRUE)) {
      cat("   ✅", dep, ":", as.character(packageVersion(dep)), "\n")
    } else {
      cat("   ❌", dep, ": 缺失\n")
    }
  }

  # 4. 测试 LDM 基本功能
  cat("\n4. 测试 LDM 基本功能:\n")

  # 测试 1: 加载命名空间
  cat("   测试 1: 加载命名空间... ")
  tryCatch({
    loadNamespace("LDM")
    cat("通过\n")
  }, error = function(e) {
    cat("失败:", conditionMessage(e), "\n")
  })

  # 测试 2: 检查 permanovaFL 函数是否存在
  cat("   测试 2: permanovaFL 函数... ")
  if (exists("permanovaFL", where = asNamespace("LDM"))) {
    cat("存在\n")
  } else {
    cat("不存在\n")
  }

  # 测试 3: 尝试运行 permanovaFL（小规模测试）
  cat("   测试 3: permanovaFL 小规模测试... ")
  tryCatch({
    set.seed(123)
    Y_test <- matrix(rnorm(20), nrow = 5, ncol = 4)
    X_test <- matrix(rnorm(10), nrow = 5, ncol = 2)
    M_test <- matrix(rnorm(10), nrow = 5, ncol = 2)

    result <- LDM::permanovaFL(Y = Y_test, X = X_test, M = M_test, nperm = 9)
    cat("通过\n")
    cat("   结果:", if (!is.null(result)) "成功" else "失败", "\n")
  }, error = function(e) {
    cat("失败:", conditionMessage(e), "\n")
  }, warning = function(w) {
    cat("警告:", conditionMessage(w), "\n")
  })

} else {
  cat("   ❌ LDM 未安装\n")
  cat("\n   安装命令:\n")
  cat("   install.packages('devtools')\n")
  cat("   devtools::install_github('yijuanhu/LDM')\n")
}

# 5. 检查 vegan 包（替代方案）
cat("\n5. 检查 vegan 包（替代方案）:\n")
if (require("vegan", character.only = TRUE, quietly = TRUE)) {
  cat("   ✅ vegan 已安装，版本:", as.character(packageVersion("vegan")), "\n")
  cat("   可以使用 PERMANOVA (adonis2) 作为替代\n")
} else {
  cat("   ❌ vegan 未安装\n")
}

cat("\n========================================\n")
cat("  诊断完成\n")
cat("========================================\n")

