# PERMANOVA-med 中介分析脚本
# 基于 LDM 包的 permanovaFL 函数
# 注意：LDM 6.0.1 要求数据为非负值（微生物 OTU 数据）

args <- commandArgs(trailingOnly = TRUE)

if (length(args) < 3) {
  stop("Usage: Rscript permanova_med.R <input.json> <output.json> <error.txt>")
}

input_file <- args[1]
output_file <- args[2]
error_file <- args[3]

tryCatch({
  # 加载必要包
  if (!require("jsonlite", character.only = TRUE, quietly = TRUE)) {
    stop("jsonlite package not installed")
  }

  if (!require("LDM", character.only = TRUE, quietly = TRUE)) {
    stop("LDM package not installed. Install from: https://github.com/yijuanhu/LDM")
  }

  cat("[PERMANOVA-med] LDM version:", as.character(packageVersion("LDM")), "\n")

  # 读取输入参数
  params <- jsonlite::fromJSON(input_file)
  cat("[PERMANOVA-med] Input loaded\n")

  # 提取数据
  outcome_data <- as.matrix(params$outcomeData)
  mediator_data <- as.matrix(params$mediatorData)
  predictor_data <- as.matrix(params$predictorData)

  permutations <- as.numeric(params$permutations) %||% 999

  cat("[PERMANOVA-med] Data dimensions:\n")
  cat("  Outcome (Y):", nrow(outcome_data), "x", ncol(outcome_data), "\n")
  cat("  Mediator (M):", nrow(mediator_data), "x", ncol(mediator_data), "\n")
  cat("  Predictor (X):", nrow(predictor_data), "x", ncol(predictor_data), "\n")
  cat("  Permutations:", permutations, "\n")

  # 检查数据一致性
  n_samples <- nrow(outcome_data)
  if (nrow(mediator_data) != n_samples || nrow(predictor_data) != n_samples) {
    stop("样本数量不一致：Y=", n_samples, ", M=", nrow(mediator_data), ", X=", nrow(predictor_data))
  }

  # LDM::permanovaFL 要求 outcome_data（OTU 表）为非负值
  # 如果有负值，需要进行转换或标准化
  if (any(outcome_data < 0, na.rm = TRUE)) {
    cat("[PERMANOVA-med] Warning: Outcome data contains negative values\n")
    cat("[PERMANOVA-med] Applying centering transformation...\n")

    # 方法 1: 最小值平移（使所有值为非负）
    min_val <- min(outcome_data, na.rm = TRUE)
    if (min_val < 0) {
      outcome_data <- outcome_data - min_val
      cat("[PERMANOVA-med] Shifted by:", -min_val, "\n")
    }
  }

  # 创建样本数据框
  sample_ids <- paste0("S", 1:n_samples)
  sample_data <- data.frame(
    SampleID = sample_ids,
    stringsAsFactors = FALSE
  )

  # 添加预测变量（X）
  if (ncol(predictor_data) == 1) {
    sample_data$X1 <- predictor_data[, 1]
  } else {
    for (i in 1:ncol(predictor_data)) {
      sample_data[[paste0("X", i)]] <- predictor_data[, i]
    }
  }

  # 添加中介变量（M）
  if (ncol(mediator_data) == 1) {
    sample_data$M1 <- mediator_data[, 1]
  } else {
    for (i in 1:ncol(mediator_data)) {
      sample_data[[paste0("M", i)]] <- mediator_data[, i]
    }
  }

  # 添加协变量（如果有）
  has_covariates <- FALSE
  if (!is.null(params$covariates)) {
    covariates <- as.matrix(params$covariates)
    if (nrow(covariates) == n_samples && ncol(covariates) > 0) {
      has_covariates <- TRUE
      for (i in 1:ncol(covariates)) {
        sample_data[[paste0("Z", i)]] <- covariates[, i]
      }
      cat("  Covariates (Z):", ncol(covariates), "\n")
    }
  }

  # 构建公式
  x_vars <- grep("^X\\d+$", names(sample_data), value = TRUE)
  m_vars <- grep("^M\\d+$", names(sample_data), value = TRUE)
  z_vars <- grep("^Z\\d+$", names(sample_data), value = TRUE)

  x_formula <- paste(x_vars, collapse = " + ")
  m_formula <- paste(m_vars, collapse = " + ")

  if (has_covariates && length(z_vars) > 0) {
    z_formula <- paste(z_vars, collapse = " + ")
    formula_str <- paste("outcome_data ~", x_formula, "+", m_formula, "+", z_formula)
  } else {
    formula_str <- paste("outcome_data ~", x_formula, "+", m_formula)
  }

  cat("[PERMANOVA-med] Formula:", formula_str, "\n")
  formula <- as.formula(formula_str)

  # 执行 PERMANOVA-med 分析
  # 关键参数：
  # - scale.otu.table=FALSE: 因为我们的是普通数据，不是 OTU 表
  # - square.dist=TRUE: 使用欧氏距离的平方
  # - center.dist=TRUE: 中心化距离矩阵
  cat("[PERMANOVA-med] Running permanovaFL (scale.otu.table=FALSE)...\n")

  result <- tryCatch({
    LDM::permanovaFL(
      formula = formula,
      data = sample_data,
      n.perm.max = permutations,
      test.mediation = TRUE,
      scale.otu.table = FALSE,  # 关键：数据不是 OTU 表，不需要标准化
      square.dist = TRUE,
      center.dist = TRUE,
      verbose = TRUE
    )
  }, error = function(e) {
    cat("[PERMANOVA-med] Error in permanovaFL:", conditionMessage(e), "\n")
    NULL
  })

  if (is.null(result)) {
    stop("permanovaFL analysis failed - LDM 包可能与当前 R 版本不兼容")
  }

  # 提取结果
  cat("[PERMANOVA-med] Extracting results...\n")

  # 全局效应
  global_effect <- list()
  if (!is.null(result$global)) {
    global_effect <- list(
      statistic = result$global$statistic %||% 0,
      p_value = result$global$p_value %||% 1,
      R2 = result$global$R2 %||% 0
    )
  }

  # 中介效应
  mediator_effects <- list()
  if (!is.null(result$mediation)) {
    cat("[PERMANOVA-med] Mediation results found\n")
    mediator_effects <- list(
      indirect_effect = result$mediation$indirect %||% 0,
      direct_effect = result$mediation$direct %||% 0,
      total_effect = result$mediation$total %||% 0,
      p_value = result$mediation$p_value %||% 1
    )
  } else if (!is.null(result$mediator)) {
    cat("[PERMANOVA-med] Mediator results found\n")
    if (is.data.frame(result$mediator)) {
      for (i in 1:nrow(result$mediator)) {
        mediator_effects[[i]] <- list(
          variable = rownames(result$mediator)[i],
          indirect_effect = result$mediator$indirect[i] %||% 0,
          direct_effect = result$mediator$direct[i] %||% 0,
          total_effect = result$mediator$total[i] %||% 0,
          p_value = result$mediator$p_value[i] %||% 1,
          proportion_mediated = result$mediator$prop[i] %||% 0
        )
      }
    }
  }

  # 构建输出
  output <- list(
    success = TRUE,
    method = "PERMANOVA-med",
    ldm_version = as.character(packageVersion("LDM")),
    permutations = permutations,
    sample_size = n_samples,
    global_effect = global_effect,
    mediator_effects = mediator_effects,
    model_info = list(
      outcome_vars = ncol(outcome_data),
      mediator_vars = ncol(mediator_data),
      predictor_vars = ncol(predictor_data),
      covariates_vars = if (has_covariates) length(z_vars) else 0,
      formula = formula_str,
      data_transformed = any(params$outcomeData < 0, na.rm = TRUE)
    ),
    timestamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  )

  # 输出 JSON
  output_json <- jsonlite::toJSON(output, auto_unbox = TRUE, pretty = TRUE)
  writeLines(output_json, output_file)

  cat("[PERMANOVA-med] Analysis completed successfully\n")
  cat("[PERMANOVA-med] Output written to:", output_file, "\n")

}, error = function(e) {
  error_msg <- paste("[PERMANOVA-med] Error:", conditionMessage(e))
  cat(error_msg, "\n")
  writeLines(error_msg, error_file)
  quit(status = 1)
})

