@echo off
echo ========================================
echo   安装 devtools 和 LDM（清华镜像）
echo ========================================
echo.

set RSCRIPT=r-portable\bin\Rscript.exe

if not exist %RSCRIPT% (
    echo ❌ 错误：未找到 R
    echo 请确认 R 4.3.3 已安装到 r-portable 目录
    echo.
    pause
    exit /b 1
)

echo R 路径：%RSCRIPT%
echo.
echo 验证 R 版本：
%RSCRIPT% --version
echo.

echo ========================================
echo   步骤 1: 设置镜像并安装 devtools
echo ========================================
echo.
echo 使用清华镜像：https://mirrors.tuna.tsinghua.edu.cn/CRAN/
echo.

%RSCRIPT% -e "options(repos = c(CRAN = 'https://mirrors.tuna.tsinghua.edu.cn/CRAN/')); install.packages('devtools', type='binary', dependencies=FALSE)"

if %ERRORLEVEL% NEQ 0 (
    echo.
    echo ⚠️ devtools 安装可能不完整，继续尝试...
    echo.
)

echo.
echo ========================================
echo   步骤 2: 安装 LDM 包
echo ========================================
echo.

%RSCRIPT% -e "options(repos = c(CRAN = 'https://mirrors.tuna.tsinghua.edu.cn/CRAN/')); if (!require('remotes', quietly=TRUE)) install.packages('remotes', type='binary'); remotes::install_github('yijuanhu/LDM', dependencies=FALSE)"

if %ERRORLEVEL% EQU 0 (
    echo.
    echo ✅ LDM 安装完成！
    echo.
) else (
    echo.
    echo ❌ LDM 安装失败，尝试手动安装依赖...
    echo.
)

echo.
echo ========================================
echo   步骤 3: 验证安装
echo ========================================
echo.

%RSCRIPT% -e "library(LDM); cat('✅ LDM 版本:', as.character(packageVersion('LDM')), '\n')"

echo.
pause

@echo off
echo ========================================
echo   安装 LDM 依赖包（批处理）
echo ========================================
echo.

set RSCRIPT=r-portable\bin\Rscript.exe

if not exist %RSCRIPT% (
    echo ❌ 错误：未找到 R
    echo.
    pause
    exit /b 1
)

echo 使用清华镜像安装基础依赖包...
echo.

%RSCRIPT% -e "options(repos = c(CRAN = 'https://mirrors.tuna.tsinghua.edu.cn/CRAN/')); install.packages(c('Rcpp', 'stringi', 'curl', 'gitcreds', 'cli', 'glue', 'rlang', 'fs', 'processx', 'desc', 'lifecycle', 'utf8', 'pillar', 'vctrs', 'cachem', 'commonmark', 'xml2', 'fontawesome', 'httpuv', 'later', 'ragg', 'tinytex', 'xtable', 'crayon', 'whisker', 'purrr', 'diffobj', 'magrittr', 'systemfonts', 'textshaping', 'base64enc'), type='binary')"

echo.
echo ========================================
echo   安装 devtools
echo ========================================
echo.

%RSCRIPT% -e "options(repos = c(CRAN = 'https://mirrors.tuna.tsinghua.edu.cn/CRAN/')); install.packages('devtools', type='binary')"

echo.
echo ========================================
echo   安装 LDM
