arguments.content:
# PERMANOVA-med 中介分析脚本（两步法）
# 基于 vegan 包的 adonis2 函数，不依赖 LDM 包
#
# 方法：
# 步骤 1: 检验 X -> M 的效应（预测变量对中介变量的影响）
# 步骤 2: 检验 X + M -> Y 的效应（加入中介变量后，预测变量对结果的影响）
# 推断：如果 X 对 M 显著，且加入 M 后 X 对 Y 的效应减弱，则存在中介效应

args <- commandArgs(trailingOnly = TRUE)

if (length(args) < 3) {
  stop("Usage: Rscript permanova_med_2step.R <input.json> <output.json> <error.txt>")
}

input_file <- args[1]
output_file <- args[2]
error_file <- args[3]

tryCatch({
  # 加载必要包
  if (!require("jsonlite", character.only = TRUE, quietly = TRUE)) {
    stop("jsonlite package not installed")
  }

  if (!require("vegan", character.only = TRUE, quietly = TRUE)) {
    stop("vegan package not installed")
  }

  cat("[PERMANOVA-med-2step] vegan version:", as.character(packageVersion("vegan")), "\n")

  # 读取输入参数
  params <- jsonlite::fromJSON(input_file)
  cat("[PERMANOVA-med-2step] Input loaded\n")

  # 提取数据
  outcome_data <- as.matrix(params$outcomeData)
  mediator_data <- as.matrix(params$mediatorData)
  predictor_data <- as.matrix(params$predictorData)

  permutations <- if (is.null(params$permutations) || is.na(params$permutations)) 999 else as.numeric(params$permutations)

  cat("[PERMANOVA-med-2step] Data dimensions:\n")
  cat("  Outcome (Y):", nrow(outcome_data), "x", ncol(outcome_data), "\n")
  cat("  Mediator (M):", nrow(mediator_data), "x", ncol(mediator_data), "\n")
  cat("  Predictor (X):", nrow(predictor_data), "x", ncol(predictor_data), "\n")
  cat("  Permutations:", permutations, "\n")

  # 检查数据一致性
  n_samples <- nrow(outcome_data)
  if (nrow(mediator_data) != n_samples || nrow(predictor_data) != n_samples) {
    stop("样本数量不一致：Y=", n_samples, ", M=", nrow(mediator_data), ", X=", nrow(predictor_data))
  }

  # 创建样本数据框
  sample_ids <- paste0("S", 1:n_samples)
  sample_data <- data.frame(
    SampleID = sample_ids,
    stringsAsFactors = FALSE
  )

  # 添加预测变量（X）
  if (ncol(predictor_data) == 1) {
    sample_data$X1 <- predictor_data[, 1]
  } else {
    for (i in 1:ncol(predictor_data)) {
      sample_data[[paste0("X", i)]] <- predictor_data[, i]
    }
  }

  # 添加中介变量（M）
  if (ncol(mediator_data) == 1) {
    sample_data$M1 <- mediator_data[, 1]
  } else {
    for (i in 1:ncol(mediator_data)) {
      sample_data[[paste0("M", i)]] <- mediator_data[, i]
    }
  }

  # 添加协变量（如果有）
  has_covariates <- FALSE
  if (!is.null(params$covariates)) {
    covariates <- as.matrix(params$covariates)
    if (nrow(covariates) == n_samples && ncol(covariates) > 0) {
      has_covariates <- TRUE
      for (i in 1:ncol(covariates)) {
        sample_data[[paste0("Z", i)]] <- covariates[, i]
      }
      cat("  Covariates (Z):", ncol(covariates), "\n")
    }
  }

  # 构建变量列表
  x_vars <- grep("^X\\d+$", names(sample_data), value = TRUE)
  m_vars <- grep("^M\\d+$", names(sample_data), value = TRUE)
  z_vars <- grep("^Z\\d+$", names(sample_data), value = TRUE)

  # ====================
  # 步骤 1: X -> M
  # ====================
  cat("\n[PERMANOVA-med-2step] Step 1: Testing X -> M effect\n")

  x_formula <- paste(x_vars, collapse = " + ")
  m_formula <- paste(m_vars, collapse = " + ")

  if (has_covariates && length(z_vars) > 0) {
    z_formula <- paste(z_vars, collapse = " + ")
    formula1_str <- paste(m_formula, "~", x_formula, "+", z_formula)
  } else {
    formula1_str <- paste(m_formula, "~", x_formula)
  }

  cat("  Formula:", formula1_str, "\n")
  formula1 <- as.formula(formula1_str)

  result_XM <- tryCatch({
    vegan::adonis2(formula1, data = sample_data, permutations = permutations, method = "bray")
  }, error = function(e) {
    cat("[PERMANOVA-med-2step] Error in step 1:", conditionMessage(e), "\n")
    NULL
  })

  if (!is.null(result_XM)) {
    cat("  R²:", result_XM$R2[1], "\n")
    cat("  p-value:", result_XM$`Pr(>F)`[1], "\n")
  }

  # ====================
  # 步骤 2: X + M -> Y
  # ====================
  cat("\n[PERMANOVA-med-2step] Step 2: Testing X + M -> Y effect\n")

  if (has_covariates && length(z_vars) > 0) {
    formula2_str <- paste("outcome_data ~", x_formula, "+", m_formula, "+", z_formula)
  } else {
    formula2_str <- paste("outcome_data ~", x_formula, "+", m_formula)
  }

  cat("  Formula:", formula2_str, "\n")
  formula2 <- as.formula(formula2_str)

  result_XMY <- tryCatch({
    vegan::adonis2(formula2, data = sample_data, permutations = permutations, method = "bray")
  }, error = function(e) {
    cat("[PERMANOVA-med-2step] Error in step 2:", conditionMessage(e), "\n")
    NULL
  })

  if (!is.null(result_XMY)) {
    cat("  X effect R²:", result_XMY$R2[1], "\n")
    cat("  X effect p-value:", result_XMY$`Pr(>F)`[1], "\n")
    if (length(result_XMY$R2) > 1) {
      cat("  M effect R²:", result_XMY$R2[2], "\n")
      cat("  M effect p-value:", result_XMY$`Pr(>F)`[2], "\n")
    }
  }

  # ====================
  # 推断中介效应
  # ====================
  cat("\n[PERMANOVA-med-2step] Inferring mediation effect\n")

  # 提取统计量
  xm_r2 <- if (!is.null(result_XM)) result_XM$R2[1] else NA
  xm_p <- if (!is.null(result_XM)) result_XM$`Pr(>F)`[1] else NA

  x_effect_r2 <- if (!is.null(result_XMY)) result_XMY$R2[1] else NA
  x_effect_p <- if (!is.null(result_XMY)) result_XMY$`Pr(>F)`[1] else NA

  m_effect_r2 <- if (!is.null(result_XMY) && length(result_XMY$R2) > 1) result_XMY$R2[2] else NA
  m_effect_p <- if (!is.null(result_XMY) && length(result_XMY$`Pr(>F)`) > 1) result_XMY$`Pr(>F)`[2] else NA

  # 中介效应判断
  mediation_evidence <- "Insufficient evidence"
  if (!is.na(xm_r2) && !is.na(xm_p) && !is.na(x_effect_r2) && !is.na(x_effect_p)) {
    if (xm_p < 0.05 && m_effect_p < 0.05) {
      mediation_evidence <- "Strong evidence"
    } else if (xm_p < 0.1 && m_effect_p < 0.1) {
      mediation_evidence <- "Moderate evidence"
    }
  }

  cat("  Mediation evidence:", mediation_evidence, "\n")

  # ====================
  # 构建输出
  # ====================
  output <- list(
    success = TRUE,
    method = "PERMANOVA-med (Two-step)",
    description = "Mediation analysis using two-step PERMANOVA approach",
    vegan_version = as.character(packageVersion("vegan")),
    permutations = permutations,
    sample_size = n_samples,
    step1_XM = list(
      formula = formula1_str,
      R2 = xm_r2,
      p_value = xm_p,
      description = "Effect of X on M"
    ),
    step2_XMY = list(
      formula = formula2_str,
      X_effect = list(
        R2 = x_effect_r2,
        p_value = x_effect_p
      ),
      M_effect = list(
        R2 = m_effect_r2,
        p_value = m_effect_p
      ),
      description = "Effect of X and M on Y"
    ),
    mediation_inference = list(
      evidence = mediation_evidence,
      interpretation = if (mediation_evidence == "Strong evidence") {
        "Significant mediation effect detected"
      } else if (mediation_evidence == "Moderate evidence") {
        "Suggestive mediation effect"
      } else {
        "No significant mediation effect detected"
      }
    ),
    model_info = list(
      outcome_vars = ncol(outcome_data),
      mediator_vars = ncol(mediator_data),
      predictor_vars = ncol(predictor_data),
      covariates_vars = if (has_covariates) length(z_vars) else 0
    ),
    timestamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  )

  # 输出 JSON
  output_json <- jsonlite::toJSON(output, auto_unbox = TRUE, pretty = TRUE)
  writeLines(output_json, output_file)

  cat("\n[PERMANOVA-med-2step] Analysis completed successfully\n")
  cat("[PERMANOVA-med-2step] Output written to:", output_file, "\n")

}, error = function(e) {
  error_msg <- paste("[PERMANOVA-med-2step] Error:", conditionMessage(e))
  cat(error_msg, "\n")
  writeLines(error_msg, error_file)
  quit(status = 1)
})

