async loadMedDemo() {
  try {
    const resp = await fetch('/r-demo/permanova-med.json');
    if (!resp.ok) throw new Error('HTTP ' + resp.status);
    const d = await resp.json();
    this.medParams.mediatorStr  = JSON.stringify(d.mediatorData);
    this.medParams.predictorStr = JSON.stringify(d.predictorData);
    this.medParams.outcomeStr   = JSON.stringify(d.outcomeData);
    this.medParams.covariateStr = '';
    this.medParams.permutations = 100;
    this.medError = '';
    this.showMessage('success', '已载入演示数据：50 样本 × 120 物种');
  } catch (e) {
    this.showMessage('error', '演示数据载入失败：' + e.message);
  }
},

async submitMed() {
  this.medError = '';
  this.analysisResult = null;

  const toMatrix = (str, label) => {
    const raw = JSON.parse(str);
    const m = Array.isArray(raw[0]) ? raw : raw.map(v => [v]); // 允许一维数组
    if (!Array.isArray(raw) || raw.length < 3) throw new Error(label + ' 至少需要 3 个样本');
    return m;
  };

  let params;
  try {
    if (!this.medParams.mediatorStr.trim())  throw new Error('请填写中介矩阵 M');
    if (!this.medParams.predictorStr.trim()) throw new Error('请填写暴露 X');
    if (!this.medParams.outcomeStr.trim())   throw new Error('请填写结局 Y');

    const mediator  = toMatrix(this.medParams.mediatorStr,  '中介矩阵 M');
    const predictor = toMatrix(this.medParams.predictorStr, '暴露 X');
    const outcome   = toMatrix(this.medParams.outcomeStr,   '结局 Y');

    const n = mediator.length;
    if (predictor.length !== n) throw new Error(`样本数不一致：M=${n}, X=${predictor.length}`);
    if (outcome.length !== n)   throw new Error(`样本数不一致：M=${n}, Y=${outcome.length}`);

    params = {
      mediatorData:  mediator,
      predictorData: predictor,
      outcomeData:   outcome,
      permutations:  this.medParams.permutations || 999
    };
    if (this.medParams.covariateStr.trim()) {
      params.covariates = toMatrix(this.medParams.covariateStr, '协变量 Z');
    }
  } catch (e) {
    this.medError = e.message;
    return;
  }

  this.loading = true;
  try {
    const result = await runPERMANOVA_Med(params);
    this.analysisResult = result;
    const p = result.mediation_p;
    this.showMessage(
      result.significant_mediation ? 'success' : 'info',
      `中介分析完成：中介效应 p = ${p}${result.n_perm_used !== result.n_perm_requested ? `（置换已修正为 ${result.n_perm_used}）` : ''}`
    );
  } catch (error) {
    this.medError = error.message || String(error);
    this.showMessage('error', '分析失败：' + this.medError);
  } finally {
    this.loading = false;
  }
},

