.loading-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: white;
}

/* ===== PERMANOVA-med 结果摘要 ===== */
.med-summary {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-left: 4px solid #6366f1;
  border-radius: 8px;
  padding: 16px 20px;
  margin-bottom: 16px;
}

.med-headline {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.med-label {
  font-size: 14px;
  color: #6b7280;
}

.med-p {
  font-size: 26px;
  font-weight: 700;
  font-family: monospace;
}

.med-p.sig  { color: #16a34a; }
.med-p.nsig  { color: #9ca3af; }

.med-badge {
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
}

.med-badge.sig  { background: #dcfce7; color: #15803d; }
.med-badge.nsig { background: #f3f4f6; color: #6b7280; }

.med-interp {
  margin: 12px 0;
  color: #374151;
  line-height: 1.6;
}

.med-table {
  width: 100%;
  border-collapse: collapse;
  margin: 12px 0;
  font-size: 14px;
}

.med-table th,
.med-table td {
  border: 1px solid #e5e7eb;
  padding: 8px 12px;
  text-align: left;
}

.med-table th {
  background: #f9fafb;
  font-weight: 600;
}

.med-table .p-sig {
  color: #16a34a;
  font-weight: 600;
}

.med-meta {
  margin-top: 8px;
  font-size: 13px;
  color: #6b7280;
}

.med-meta code {
  background: #f3f4f6;
  padding: 2px 6px;
  border-radius: 4px;
}
</style>

