if (file.exists(f_out)) {
  r <- fromJSON(f_out)
  cat("\n>>> 演示子集验证：中介 p =", r$mediation_p,
      "| 显著 =", r$significant_mediation, "\n")
  ct <- r$covariate_tests           # jsonlite 会把对象数组简化为 data.frame
  if (is.data.frame(ct)) {
    for (i in seq_len(nrow(ct))) {
      cat(sprintf(">>> %-14s F = %6.3f  R2 = %6.4f  p = %s\n",
