    中介非负整数: d.mediatorData.every(r => r.length === d.taxa && r.every(v => Number.isInteger(v) && v >= 0)),
    全有限值: allFinite(d.mediatorData) && allFinite(d.predictorData) && allFinite(d.outcomeData)
              && (!d.covariates || allFinite(d.covariates)),
    X方差: +(Math.variance ? 0 : 0),
  };
  const flat = d.predictorData.flat();
  checks.X非常量 = new Set(flat).size > 1;
  const flatY = d.outcomeData.flat();
  checks.Y非常量 = new Set(flatY).size > 1;
  if (!checks.全有限值 || !checks.X非常量 || !checks.Y非常量) console.log('异常明细', it.id, d.asColumns);
  const payload = { mediatorData: d.mediatorData, predictorData: d.predictorData,
                    outcomeData: d.outcomeData, ...(d.covariates ? { covariates: d.covariates } : {}),
                    permutations: 100, seed: 12345 };
  fs.writeFileSync(`r-scripts/tmp_med/in_${it.id}.json`, JSON.stringify(payload));
  rows.push({ id: it.id, n: d.n, 物种: d.taxa, ...checks, 公式: d.formula });
}
console.log('模板总数:', MED_TEMPLATE_COUNT);
console.table(rows.map(r => ({ id: r.id, n: r.n, 物种: r.物种, 行列一致: r.行列一致, 非负整数: r.中介非负整数, 全有限: r.全有限值, X变动: r.X非常量, Y变动: r.Y非常量 })));
const bad = rows.filter(r => !(r.行列一致 && r.中介非负整数 && r.全有限值 && r.X非常量 && r.Y非常量));
console.log(bad.length ? `❌ ${bad.length} 个异常: ${bad.map(b=>b.id)}` : '✅ 全部 25 个模板数据合法（严格有限性校验）');
console.log('\n含协变量/多变量分组公式:');
rows.filter(r=>r.公式.includes('|')||r.公式.includes('(')).forEach(r=>console.log('  ', r.id.padEnd(24), r.公式));
EOF
