export function buildMedTemplateData(spec) {
  // 默认样本量按功效规则上调（与 R 侧标定结果一致）：
  //   • 二分类结局检验功效低 → ×1.6
  //   • 多分类（≥3 程度）暴露产生的群落梯度较缓 → ×1.4
