import { MED_TEMPLATE_GROUPS, MED_TEMPLATE_MAP, MED_TEMPLATE_COUNT, buildMedTemplateData } from './medTemplates.mjs';
import fs from 'fs';

const allFinite = (v) => Array.isArray(v) ? v.every(allFinite) : (typeof v === 'number' && Number.isFinite(v));
const rows = [];
for (const g of MED_TEMPLATE_GROUPS) for (const it of g.items) {
  const d = buildMedTemplateData(it.spec);
  const checks = {
    行列一致: d.predictorData.length === d.n && d.outcomeData.length === d.n,
    非负整数: d.mediatorData.every(r => r.length === d.taxa && r.every(v => Number.isInteger(v) && v >= 0)),
    全有限: allFinite(d.mediatorData) && allFinite(d.predictorData) && allFinite(d.outcomeData)
            && (!d.covariates || allFinite(d.covariates)),
    X变动: new Set(d.predictorData.flat()).size > 1,
    Y变动: new Set(d.outcomeData.flat()).size > 1,
  };
  fs.writeFileSync(`r-scripts/tmp_med/in_${it.id}.json`, JSON.stringify({
    mediatorData: d.mediatorData, predictorData: d.predictorData, outcomeData: d.outcomeData,
    ...(d.covariates ? { covariates: d.covariates } : {}), permutations: 100, seed: 12345 }));
  rows.push({ id: it.id, n: d.n, 物种: d.taxa, ...checks });
}
console.log('模板总数:', MED_TEMPLATE_COUNT);
const bad = rows.filter(r => !(r.行列一致 && r.非负整数 && r.全有限 && r.X变动 && r.Y变动));
console.log(bad.length ? `❌ ${bad.length} 个异常: ${bad.map(b=>b.id).join(',')}` : '✅ 25 个模板数据合法');
console.log('实际样本量(含功效加成):', rows.map(r=>r.n).join(','));
EOF
