  { coef:0.05, med:1.8, noise:0.40, frac:0.55 },
  { coef:0.04, med:2.4, noise:0.35, frac:0.60 },
  { coef:0.03, med:3.0, noise:0.30, frac:0.65 },
];
const patch = (s,c)=>s.replace(/spec\.coef \?\? [\d.]+/g,`spec.coef ?? ${c.coef}`)
  .replace(/spec\.medStrength \?\? [\d.]+/g,`spec.medStrength ?? ${c.med}`)
  .replace(/spec\.noise \?\? [\d.]+/g,`spec.noise ?? ${c.noise}`)
  .replace(/taxa \* 0\.55/g,`taxa * ${c.frac}`);
for (const [i,c] of combos.entries()) {
  const f = `r-scripts/tmp_med/b${i}.mjs`;
  fs.writeFileSync(f, patch(base,c));
  const m = await import(`./b${i}.mjs?x=${i}`);
  const out = [];
  for (const id of ids) {
