  fs.writeFileSync(inp, JSON.stringify({ mediatorData:d.mediatorData, predictorData:d.predictorData,
    outcomeData:d.outcomeData, ...(d.covariates?{covariates:d.covariates}:{}), permutations:100, seed:12345 }));
