  const o = `r-scripts/tmp_med/t_${id}.out.json`;
  if (!fs.existsSync(o)) return { id, tag, p: 'ERR' };
  const j = JSON.parse(fs.readFileSync(o,'utf8'));
  return { id, tag, n:d.n, p:j.mediation_p, sig:j.significant_mediation?'✓':'✗',
