out.push(runOne('foodSafetyMed', { coef:0.08, responsive:6, zResponsive:2, medStrength:3.0 }, 'resp6,zR2,c.08'));
out.push(runOne('foodSafetyMed', { coef:0.05, responsive:8, zResponsive:1, medStrength:4.0, noise:0.3 }, 'resp8,zR1,med4,n.3'));
console.table(out);
