import medDemoData from '@/assets/permanova-med.json';
// 25 个中介分析演示模板（与 PERMANOVA 模板数量/学科方向对齐，经 R 实测验证）
import { MED_TEMPLATE_GROUPS, MED_TEMPLATE_MAP, buildMedTemplateData } from '@/utils/medTemplates';

async loadMedTemplate(id) {
  const item = MED_TEMPLATE_MAP[id];
  if (!item) {
    this.medError = `未知模板：${id}`;
    return;
  }
  try {
    const d = buildMedTemplateData(item.spec);
    this.medParams.mediatorStr  = JSON.stringify(d.mediatorData);
    this.medParams.predictorStr = JSON.stringify(d.predictorData);
    this.medParams.outcomeStr   = JSON.stringify(d.outcomeData);
    this.medParams.covariateStr = d.covariates ? JSON.stringify(d.covariates) : '';
    this.medParams.permutations = 100;
    this.medParams.selectedTemplate = id;
    this.medParams.summary = `${d.n} 样本 × ${d.taxa} 物种｜公式 ${d.formula}`;
    this.medParams.desc = item.spec.note || item.tip;
    this.medManualOpen = false;
    this.medError = '';
    this.analysisResult = null;
    this.showMessage('success', `已载入模板「${item.label}」：${d.n} 样本 × ${d.taxa} 物种`);
  } catch (e) {
    this.medError = '模板生成失败：' + e.message;
    this.showMessage('error', '模板生成失败：' + e.message);
  }
},

clearMedTemplate() {
  this.medParams.selectedTemplate = '';
  this.medParams.summary = '';
  this.medParams.desc = '';
  this.medParams.mediatorStr = '';
  this.medParams.predictorStr = '';
  this.medParams.outcomeStr = '';
  this.medParams.covariateStr = '';
  this.analysisResult = null;
},

