// 回填模板数据
// 公式预设只描述研究设计（X→M→Y 的角色与变量名），本身不包含数据。
// 以前这里会写入 3 行假矩阵：既不是模板描述的结构，又让直接运行必然失败，
// 因此改为保留用户已有数据，并提示如何拿到可运行数据。
fillTemplateData(template) {
  const empty = !this.permanovaMedParams.mediatorDataStr.trim();
  if (empty) {
    ElMessage.info({
      message: `已应用公式预设「${template.name}」（中介：${template.mediator || 'M'}）。`
        + '该预设不含数据，请再点一个「数据模板」生成可运行数据，或用 Excel 导入自己的数据。',
      duration: 7000
    });
  } else {
    ElMessage.success(`已应用公式预设：${template.name}（当前数据保持不变）`);
  }
},

// 载入数据模板（生成并回填可直接运行的合成数据）
loadMedDataTemplate(id) {
  const item = MED_TEMPLATE_MAP[id];
  if (!item) {
    ElMessage.error(`未知数据模板：${id}`);
    return;
  }
  if (this.selectedMedDataId === id) {
    this.clearMedDataTemplate();
    return;
  }
  try {
    const d = buildMedTemplateData(item.spec);
    const p = this.permanovaMedParams;
    p.mediatorDataStr = JSON.stringify(d.mediatorData);
    p.predictorDataStr = JSON.stringify(d.predictorData);
    p.outcomeDataStr = JSON.stringify(d.outcomeData);
    p.covariatesStr = d.covariates ? JSON.stringify(d.covariates) : '';

    // 先算中介（定义样本数），再校验其他，用于行/列字典消歧
    this.validateMediatorData();
    this.validatePredictorData();
    this.validateOutcomeData();
    this.validateCovariates();

    this.selectedMedDataId = id;
    this.selectedMedDataLabel = item.label;
    this.medDataSummary = `${d.n} 样本 × ${d.taxa} 中介变量｜LDM 公式 ${d.formula}｜${item.spec.note || item.tip}`;
    this.analysisResult = null;
    ElMessage.success(`已载入数据模板：${item.label}，可直接运行分析`);
  } catch (e) {
    ElMessage.error('数据模板生成失败：' + e.message);
  }
},

clearMedDataTemplate() {
  const p = this.permanovaMedParams;
  p.mediatorDataStr = '';
  p.predictorDataStr = '';
  p.outcomeDataStr = '';
  p.covariatesStr = '';
  p.mediatorN = null;
  p.mediatorInfo = p.predictorInfo = p.outcomeInfo = p.covariatesInfo = '';
  p.mediatorDataValid = false;
  p.predictorDataValid = false;
  p.outcomeDataValid = false;
  p.covariatesValid = true;
  p.sampleMismatch = '';
  this.selectedMedDataId = null;
  this.selectedMedDataLabel = '';
  this.medDataSummary = '';
  this.analysisResult = null;
},

// 从其他矩阵推出参照样本数（用于判别对象格式是行还是列）
refSampleN(excludeField) {
  const order = ['mediatorDataStr', 'predictorDataStr', 'outcomeDataStr', 'covariatesStr'];
  for (const f of order) {
    if (f === excludeField) continue;
    const s = this.permanovaMedParams[f];
    if (!s || !s.trim()) continue;
    try {
      const d = JSON.parse(s);
      if (Array.isArray(d) && d.length > 0 && Array.isArray(d[0])) return d.length;
    } catch (e) { /* 解析不了就试下一个 */ }
  }
  return null;
},

// 统一解析三种写法，返回 { ok, n, p, rows, error }；rows 恒为 样本 × 变量
inspectMatrix(str, refN) {
  let data;
  try { data = JSON.parse(str); } catch (e) { return { ok: false, error: 'JSON 格式错误：' + e.message }; }
  if (data === null || data === undefined) return { ok: false, error: '数据为空' };

  const numeric = (v) => typeof v === 'number' && Number.isFinite(v);

  if (Array.isArray(data)) {
    if (data.length === 0) return { ok: false, error: '至少需要一个样本' };
    if (data.every(numeric)) return { ok: true, n: data.length, p: 1, rows: data.map((v) => [v]) };
    if (!data.every((r) => Array.isArray(r))) {
      return { ok: false, error: '数组形式请统一为二维数组 [[...],[...]]（或单变量时给纯数字数组）' };
    }
    const lens = [...new Set(data.map((r) => r.length))];
    if (lens.length !== 1) return { ok: false, error: `各行变量数不一致（出现 ${lens.join('/')}），可能有缺失值` };
    if (!data.every((r) => r.every(numeric))) return { ok: false, error: '存在非数值元素（null/文字/NaN），请清理' };
    return { ok: true, n: data.length, p: lens[0], rows: data };
  }

  if (typeof data === 'object') {
    const keys = Object.keys(data);
    if (keys.length === 0) return { ok: false, error: '至少需要一个样本' };
    const vals = keys.map((k) => data[k]);
    if (vals.every(numeric)) return { ok: true, n: keys.length, p: 1, rows: vals.map((v) => [v]) };
    if (!vals.every((v) => Array.isArray(v))) return { ok: false, error: '对象格式下，每个键的值必须是数组' };
    const lens = [...new Set(vals.map((v) => v.length))];
    if (lens.length !== 1) return { ok: false, error: `所有数组长度必须一致（出现 ${lens.join('/')}）` };
    if (!vals.every((v) => v.every(numeric))) return { ok: false, error: '存在非数值元素（null/文字/NaN），请清理' };

    const k = keys.length;
    const L = lens[0];
    const asRows = () => {
      const rows = [];
      for (let i = 0; i < k; i++) rows.push(vals.map((v) => v[i]));
      return rows;
    };
    const asCols = () => {
      const rows = [];
      for (let i = 0; i < L; i++) rows.push(vals.map((v) => v[i]));
      return rows;
    };

    if (refN != null) {
      if (k === refN && L !== refN) return { ok: true, n: k, p: L, rows: asRows() };
      if (L === refN && k !== refN) return { ok: true, n: L, p: k, rows: asCols() };
      if (k === refN && L === refN) return { ok: true, n: k, p: L, rows: asRows() };  // 方阵消不了歧，按行字典
      return { ok: false, error: `样本数无法对齐（记录数=${k}，每条长度=${L}，参照样本数=${refN}）。` +
        '行字典请让记录数=样本数，列字典请让数组长度=样本数' };
    }
    // 无参照时：按行字典解释（与 Excel 导入、输入框示例一致）
    return { ok: true, n: k, p: L, rows: asRows() };
  }

  return { ok: false, error: '无法识别的数据类型' };
},

// 校验四个矩阵的样本数是否一致（不一致时直接在前端抦住，不等到 R 报错）
checkSampleConsistency() {
  const p = this.permanovaMedParams;
  p.sampleMismatch = '';
  const fields = [
    ['中介 M', 'mediatorDataStr'],
    ['暴露 X', 'predictorDataStr'],
    ['结局 Y', 'outcomeDataStr'],
    ['协变量 Z', 'covariatesStr'],
  ];
  const seen = [];
  for (const [label, f] of fields) {
    const s = p[f];
    if (!s || !s.trim()) continue;
    const ref = f === 'mediatorDataStr' ? p.mediatorN : p.mediatorN;
    const r = this.inspectMatrix(s, ref);
    if (r.ok) seen.push({ label, n: r.n });
  }
  if (seen.length < 2) return;
  const bad = seen.filter((x) => x.n !== seen[0].n);
  if (bad.length) {
    p.sampleMismatch = '样本数不一致：' + seen.map((x) => `${x.label}=${x.n}`).join('，') + '（应以中介 M 的样本数为准）';
  }
},

validateOutcomeData() {

const ref = this.permanovaMedParams.mediatorN ?? this.refSampleN('outcomeDataStr');
const info = this.inspectMatrix(this.permanovaMedParams.outcomeDataStr, ref);
this.permanovaMedParams.outcomeDataValid = info.ok;
this.permanovaMedParams.outcomeDataError = info.ok ? '' : info.error;
this.permanovaMedParams.outcomeInfo = info.ok ? `${info.n} 样本 × ${info.p} 变量` : '';
this.checkSampleConsistency();

