// 生成一份 probe 输入，供 R 侧检查 LDM permanovaFL 返回对象的完整结构
import fs from 'fs';
import os from 'os';
import path from 'path';
import { pathToFileURL } from 'url';

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-'));
const dst = path.join(tmp, 'm.mjs');
fs.copyFileSync(path.join(process.cwd(), 'frontend/src/utils/medTemplates.js'), dst);
const m = await import(pathToFileURL(dst).href);
const d = m.buildMedTemplateData(m.MED_TEMPLATE_MAP['dietObesityMed'].spec);
fs.writeFileSync(
  path.join(process.cwd(), 'r-scripts/tmp_probe.in.json'),
  JSON.stringify({
    mediatorData: d.mediatorData,
    predictorData: d.predictorData,
    outcomeData: d.outcomeData,
    permutations: 100,
    seed: 12345,
  })
);
console.log('probe 输入已写出: n=' + d.n + ' taxa=' + d.taxa);
fs.rmSync(tmp, { recursive: true, force: true });

