// 渲染当前图表
renderCurrentChart() {
  const el = this.$refs.medChart;
  if (!el || !this.analysisResult) return;

  import('echarts').then((echarts) => {
    const chart = echarts.getInstanceByDom(el) || echarts.init(el);
    const builders = {
      path: () => this.buildPathChart(),
      bar: () => this.buildEffectBarChart(),
      heatmap: () => this.buildCorHeatmapChart(),
      scatter: () => this.buildScatterMatrixChart(),
      forest: () => this.buildForestChart(),
    };
    const build = builders[this.activeChartType] || builders.bar;
    chart.setOption(build(), true);
    chart.resize();
  }).catch((e) => {
    console.error('[PERMANOVA-med] 图表加载失败:', e);
  });
},

// 最小二拟线（散点矩阵用）
ols(xs, ys) {
  const n = xs.length;
  if (!n) return null;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let sxy = 0, sxx = 0;
  for (let i = 0; i < n; i++) { sxy += (xs[i] - mx) * (ys[i] - my); sxx += (xs[i] - mx) ** 2; }
  if (!sxx) return null;
  const slope = sxy / sxx;
  return { slope, intercept: my - slope * mx, xs, ys, mx };
},

// 图 1：中介路径图（节点位置固定，边上标标准化系数与 p）
buildPathChart() {
  const p = this.chartData.path;
  const linkLabel = (txt) => ({ show: true, formatter: txt, color: '#303133', fontSize: 13, fontWeight: 600, backgroundColor: '#fff', padding: [3, 6], borderRadius: 4 });
  return {
    title: { subtext: this.chartData.note, bottom: 6, left: 'center', textStyle: { fontSize: 11, color: '#909399' } },
    tooltip: { formatter: (x) => (x.dataType === 'edge' ? x.data.label.formatter : x.data.name.replace('\n', ' ')) },
    series: [{
      type: 'graph', layout: 'none', roam: false, edgeSymbol: ['none', 'arrow'], edgeSymbolSize: 10,
      symbolSize: [150, 90], label: { show: true, position: 'inside', color: '#fff', fontWeight: 600, fontSize: 14, lineHeight: 18 },
      lineStyle: { width: 2.4, curveness: 0.08, color: '#606266' },
      data: [
        { name: 'X\n暴露', x: 140, y: 210, itemStyle: { color: '#409eff' } },
        { name: 'M\n中介（群落轴）', x: 470, y: 90, itemStyle: { color: '#67c23a' } },
        { name: 'Y\n结局', x: 800, y: 210, itemStyle: { color: '#e6a23c' } },
      ],
      links: [
        { source: 0, target: 1, label: linkLabel(`a = ${this.fmt(p.a, 3)}  p=${this.fmtP(p.a_p)}`) },
        { source: 1, target: 2, label: linkLabel(`b = ${this.fmt(p.b, 3)}  p=${this.fmtP(p.b_p)}`) },
        { source: 0, target: 2, curveness: -0.25, label: linkLabel(`直接 c′ = ${this.fmt(p.c_prime, 3)}  p=${this.fmtP(p.c_prime_p)}`) },
      ],
    }],
  };
},

// 图 2：效应量柱状图
buildEffectBarChart() {
  const p = this.chartData.path;
  const rows = [
    { name: '间接效应 a×b', est: p.indirect, ci: p.indirect_ci },
    { name: '直接效应 c′', est: p.c_prime, ci: p.c_prime_ci },
    { name: '总效应', est: p.total, ci: null },
    { name: 'a：X→M轴', est: p.a, ci: p.a_ci },
    { name: 'b：M轴→Y|X', est: p.b, ci: p.b_ci },
  ];
  return {
    grid: { left: 90, right: 40, top: 50, bottom: 60 },
    tooltip: {
      formatter: (x) => {
        const r = rows[x.dataIndex];
        return `${r.name}<br/>估计：${this.fmt(r.est, 4)}` + (r.ci ? `<br/>95% CI：${this.fmt(r.ci[0], 4)} ~ ${this.fmt(r.ci[1], 4)}` : '');
      },
    },
    xAxis: { type: 'category', data: rows.map((r) => r.name), axisLabel: { interval: 0, width: 84, overflow: 'break' } },
    yAxis: { type: 'value', name: '标准化效应', zeroLine: { lineStyle: { color: '#909399' } } },
    series: [{
      type: 'bar', barWidth: '48%',
      data: rows.map((r) => ({
        value: r.est,
        itemStyle: { color: r.est != null && r.est >= 0.15 ? '#67c23a' : '#409eff' },
      })),
      label: { show: true, position: 'top', formatter: (x) => this.fmt(x.value, 3) },
    }],
  };
},

// 图 3：相关系数热图
buildCorHeatmapChart() {
  const c = this.chartData.correlation;
  const idx = { X1: 0, M_axis: 1, Y1: 2 };
  const name = (l) => (l === 'M_axis' ? 'M轴' : l);
  const data = [];
  c.matrix.forEach((row, i) => row.forEach((v, j) => data.push([j, i, v])));
  return {
    tooltip: { formatter: (x) => `${name(c.labels[x.value[1]])} × ${name(c.labels[x.value[0]])}<br/>r = ${x.value[2].toFixed(4)}` },
    grid: { left: 90, right: 30, top: 40, bottom: 90 },
    xAxis: { type: 'category', data: c.labels.map(name), splitArea: { show: true } },
    yAxis: { type: 'category', data: c.labels.map(name), splitArea: { show: true } },
    visualMap: { min: -1, max: 1, calculable: true, orient: 'horizontal', left: 'center', bottom: 10, inRange: { color: ['#3b6db3', '#f7f7f7', '#c0392b'] } },
    series: [{
      type: 'heatmap', data,
      label: { show: true, formatter: (x) => x.value[2].toFixed(2) },
      itemStyle: { borderColor: '#fff', borderWidth: 2 },
    }],
  };
},

// 图 4：X / M轴 / Y 两两散点（带拟合线）
buildScatterMatrixChart() {
  const s = this.chartData.samples;
  const pairs = [
    { x: s.x, y: s.m, xl: 'X（暴露）', yl: 'M轴' },
    { x: s.m, y: s.y, xl: 'M轴', yl: 'Y（结局）' },
    { x: s.x, y: s.y, xl: 'X（暴露）', yl: 'Y（结局）' },
  ];
  const grids = [], xAxes = [], yAxes = [], series = [], titles = [];
  pairs.forEach((pr, i) => {
    const top = 40 + i * 155;
    grids.push({ left: 70, right: 30, top, height: 110 });
    xAxes.push({ gridIndex: i, type: 'value', scale: true, name: pr.xl, nameLocation: 'middle', nameGap: 24, axisLabel: { show: false } });
    yAxes.push({ gridIndex: i, type: 'value', scale: true, name: pr.yl, nameLocation: 'middle', nameGap: 40, axisLabel: { show: false } });
    const fit = this.ols(pr.x, pr.y);
    const lineData = fit ? [
      [Math.min(...pr.x), fit.intercept + fit.slope * Math.min(...pr.x)],
      [Math.max(...pr.x), fit.intercept + fit.slope * Math.max(...pr.x)],
    ] : [];
    series.push({ type: 'scatter', xAxisIndex: i, yAxisIndex: i, symbolSize: 8, data: pr.x.map((v, k) => [v, pr.y[k]]), itemStyle: { color: '#409eff', opacity: 0.7 } });
    series.push({ type: 'line', xAxisIndex: i, yAxisIndex: i, showSymbol: false, data: lineData, lineStyle: { color: '#e6a23c', width: 2 } });
    titles.push({ text: `${pr.xl} vs ${pr.yl}`, left: 70, top: top - 22, textStyle: { fontSize: 12, color: '#606266' } });
  });
  return { title: titles, tooltip: { trigger: 'item' }, grid: grids, xAxis: xAxes, yAxis: yAxes, series };
},

// 图 5：森林图（估计值 + 95% CI）
buildForestChart() {
  const p = this.chartData.path;
  const rows = [
    { name: 'a  X→M轴', est: p.a, lo: p.a_ci[0], hi: p.a_ci[1] },
    { name: 'b  M轴→Y|X', est: p.b, lo: p.b_ci[0], hi: p.b_ci[1] },
    { name: "c' X→Y|M轴", est: p.c_prime, lo: p.c_prime_ci[0], hi: p.c_prime_ci[1] },
    { name: '间接效应 a×b', est: p.indirect, lo: p.indirect_ci[0], hi: p.indirect_ci[1] },
  ];
  return {
    grid: { left: 150, right: 50, top: 40, bottom: 50 },
    tooltip: {
      formatter: (x) => {
        const r = rows[x.dataIndex];
        return `${r.name}<br/>估计：${this.fmt(r.est, 4)}<br/>95% CI：${this.fmt(r.lo, 4)} ~ ${this.fmt(r.hi, 4)}`;
      },
    },
    xAxis: { type: 'value', name: '标准化效应', axisLine: { show: true } },
    yAxis: { type: 'category', data: rows.map((r) => r.name), axisTick: { show: false } },
    series: [
      {
        type: 'custom', name: '95% CI', z: 1,
        encode: { x: [1, 2], y: 0 },
        data: rows.map((r, i) => [i, r.lo, r.hi]),
        renderItem: (params, api) => {
          const yi = api.value(0);
          const lo = api.coord([api.value(1), yi]);
          const hi = api.coord([api.value(2), yi]);
          const h = api.size([0, 1])[1] * 0.22;
          const style = { stroke: '#409eff', lineWidth: 2 };
          return {
            type: 'group',
            children: [
              { type: 'line', shape: { x1: lo[0], y1: lo[1], x2: hi[0], y2: hi[1] }, style },
              { type: 'line', shape: { x1: lo[0], y1: lo[1] - h, x2: lo[0], y2: lo[1] + h }, style },
              { type: 'line', shape: { x1: hi[0], y1: hi[1] - h, x2: hi[0], y2: hi[1] + h }, style },
            ],
          };
        },
      },
      {
        type: 'scatter', name: '估计值', z: 2, symbolSize: 13, itemStyle: { color: '#e6a23c' },
        data: rows.map((r, i) => [i, r.est]),
        markLine: { silent: true, symbol: 'none', label: { formatter: '无效应线 0' }, lineStyle: { color: '#909399', type: 'dashed' }, data: [{ xAxis: 0 }] },
      },
    ],
  };
},

