import fs from 'node:fs';
import { execSync } from 'node:child_process';

const sh = (c) => execSync(c, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });

// 1) 未跟踪 r-portable 文件的真实体积
const raw = sh('git status --porcelain -uall -- r-portable');
const list = raw.split('\n').filter(Boolean).map((l) => l.slice(3).replace(/\\/g, '/'));
let tot = 0, n = 0, big = [];
for (const f of list) {
  try {
    const st = fs.statSync(f);
    if (!st.isFile()) continue;
    n++; tot += st.size;
    if (st.size > 45 * 1048576) big.push([f, (st.size / 1048576).toFixed(1) + 'MB']);
  } catch (e) { /* ignore */ }
}
console.log(`未跟踪 r-portable：条目 ${list.length}，实际文件 ${n}，合计 ${(tot / 1048576).toFixed(1)} MB`);
if (big.length) console.log('>45MB 单文件:', big);

// 2) 索引里有没有特殊标记（assume-unchanged / skip-worktree）
const idx = sh('git ls-files -v').split('\n').filter(Boolean);
const flags = {};
for (const l of idx) { const k = l[0]; flags[k] = (flags[k] || 0) + 1; }
console.log('git ls-files -v 状态字母分布（H=正常, h=assume-unchanged, S=skip-worktree）:', flags);
const special = idx.filter((l) => l[0] !== 'H').length;
console.log('非 H 标记的索引条目数:', special);

// 3) sparse checkout？
for (const k of ['core.sparseCheckout', 'core.skipWorktree']) {
  try { console.log(k + ':', sh(`git config --get ${k}`).trim() || '(未设置)'); } catch (e) { console.log(k + ': (未设置)'); }
}

// 4) HEAD 里随机抽 3 个 r-portable 文件，确认 blob 真的存在
const tracked = sh('git ls-files -- r-portable').split('\n').filter(Boolean);
console.log('HEAD 跟踪的 r-portable 文件数:', tracked.length);
for (const f of [tracked[0], tracked[Math.floor(tracked.length / 2)], tracked[tracked.length - 1]]) {
  let ok = 'MISSING';
  try { ok = sh(`git cat-file -s HEAD:${f.replace(/\\/g, '/')}`).trim(); } catch (e) { ok = 'ERR ' + e.message.slice(0, 40); }
  console.log(`  ${f} -> blob 字节数 ${ok}`);
}

// 5) 仓库历史体积
console.log(sh('git count-objects -vH').trim());
console.log('.git 目录占用:', sh('du -sh .git').trim());
console.log('提交数:', sh('git rev-list --count HEAD').trim(), '| 当前分支:', sh('git branch --show-current').trim());
try { console.log('LFS 是否配置:', sh('git lfs env').split('\n')[0]); } catch (e) { console.log('LFS: 未安装/未配置'); }

