arguments.content:
import fs from 'node:fs';

const f = 'scripts/setup-r-runtime.ps1';
let s = fs.readFileSync(f, 'utf8');
const BOM = '\uFEFF';
const hadBom = s.startsWith(BOM);
if (hadBom) s = s.slice(1);

let n = 0;
function rep(re, to, label) {
  if (!re.test(s)) { console.error('锚点未匹配: ' + label); process.exit(1); }
  s = s.replace(re, to); n++; console.log('  应用: ' + label);
}

// 1) UTF-8 控制台 + Run-Native 助手
rep(
  /Set-StrictMode -Version Latest\r?\n/,
  `Set-StrictMode -Version Latest
$ErrorActionPreferenceForNative = 'Continue'

# GBK 控制台下中文会乱码，尽量把输出编码拉到 UTF-8（失败不影响主流程）
try {
  [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
  $OutputEncoding = [Console]::OutputEncoding
} catch { }

# PS 5.1 里 ErrorActionPreference='Stop' 会把原生命令写到 stderr 的内容当异常抛出，
# 导致「Rscript 明明可用却被判不可用」。所有外部命令统一走这个口子。
function Run-Native {
  param([string]$Exe, [string[]]$ArgList = @())
  $prev = $ErrorActionPreference
  $ErrorActionPreference = 'Continue'
  try {
    if ($ArgList.Count) { $out = & $Exe @ArgList 2>&1 } else { $out = & $Exe 2>&1 }
    $code = $LASTEXITCODE
  } finally { $ErrorActionPreference = $prev }
  @{ Out = $out; Code = $code }
}
`, 'UTF-8 + Run-Native');

// 2) Test-Runtime 用 Run-Native
rep(
  /function Test-Runtime\(\[string\]\$dir\) \{[\s\S]*?\r?\n\}/,
  `function Test-Runtime([string]$dir) {
  $rs = Join-Path $dir 'bin\\Rscript.exe'
  if (-not (Test-Path $rs)) { return $false }
  $r = Run-Native -Exe $rs -ArgList @('--version')
  return ($r.Code -eq 0)
}`, 'Test-Runtime');

// 3) Invoke-Verify 的外部调用
rep(
  /  & \$RSCRIPT \(Join-Path \$ROOT 'r-scripts\\tools\\verify_r_runtime\.R'\)\r?\n  \$code = \$LASTEXITCODE\r?\n/,
  `  $r = Run-Native -Exe $RSCRIPT -ArgList @((Join-Path $ROOT 'r-scripts\\tools\\verify_r_runtime.R'))
  $r.Out | ForEach-Object { Write-Host $_ }
  $code = $r.Code
`, 'Invoke-Verify');

// 4) 两处 export_r_lockfile 调用
rep(
  /  & \$RSCRIPT \(Join-Path \$ROOT 'r-scripts\\tools\\export_r_lockfile\.R'\)\r?\n  return \$LASTEXITCODE\r?\n/g,
  `  $rr = Run-Native -Exe $RSCRIPT -ArgList @((Join-Path $ROOT 'r-scripts\\tools\\export_r_lockfile.R'))
  $rr.Out | ForEach-Object { Write-Host $_ }
  return $rr.Code
`, 'export_r_lockfile（两处）');

// 5) fromRepos 里生成的包安装脚本调用
rep(
  /  & \$RSCRIPT \$tmpR\r?\n  \$code = \$LASTEXITCODE\r?\n/,
  `  $rp = Run-Native -Exe $RSCRIPT -ArgList @($tmpR)
  $rp.Out | ForEach-Object { Write-Host $_ }
  $code = $rp.Code
`, 'fromRepos 包安装');

fs.writeFileSync(f + '.tmp', (hadBom ? BOM : '') + s, 'utf8');
fs.renameSync(f + '.tmp', f);
console.log('共应用 ' + n + ' 处');

