import fs from 'node:fs';

const SRC = 'frontend/src/utils/medTemplates.js';
const OUT = 'frontend/src/utils/rng.js';

const lines = fs.readFileSync(SRC, 'utf8').split('\n');
// 逐字取出「伪随机数 + zscore + round4」段落（第 17 行注释起，到 round4 定义行止）
const start = lines.findIndex((l) => l.startsWith('// ------- 伪随机数'.replace(/ -+/g, ' ')));
const s = lines.findIndex((l) => l.indexOf('mulberry32(seed)') >= 0) - 1;
const e = lines.findIndex((l) => l.startsWith('const round4'));
if (s < 0 || e < 0) { console.error('定位失败 s=' + s + ' e=' + e); process.exit(1); }
const block = lines.slice(s, e + 1).join('\n');

const header = `/**
 * 确定性伪随机数与统计小工具（共享模块）
 * ---------------------------------------------------------------
 * 演示模板必须「同一 id 每次生成完全相同的数据」，否则回归断言与用户复现都会失效，
 * 所以所有模板模块统一从这里取随机源，不各自实现。
 *
 * 注意：本文件里的实现是从 medTemplates.js 逐字抽出来的，
 * 抽出后 25 个中介模板的统计量与抽之前完全一致（verify_med_templates.mjs 25/25）。
 * 改动这里的任何数值路径都会让既有模板的标定失效，务必先跑回归。
 */

`;
const footer = `\n\nexport { mulberry32, makeRng, zscore, round4 };\n`;
fs.writeFileSync(OUT, header + block + footer, 'utf8');

// medTemplates.js：删掉本地实现，改为 import
const importLine = `import { mulberry32, makeRng, zscore, round4 } from './rng';\n`;
let body = lines.slice(0, s).concat(lines.slice(e + 1)).join('\n');
// 顶部注释块结束后插入 import（放在第一行 /** ... */ 之后）
const closeIdx = body.indexOf('*/');
if (closeIdx < 0) { console.error('未找到文件头注释结束'); process.exit(1); }
body = body.slice(0, closeIdx + 2) + '\n\n' + importLine + body.slice(closeIdx + 2).replace(/^\n+/, '\n');
fs.writeFileSync(SRC + '.tmp', body, 'utf8');
fs.renameSync(SRC + '.tmp', SRC);

console.log('rng.js 已生成（' + block.split('\n').length + ' 行原样搬运）');
console.log('medTemplates.js 头部：');
console.log(body.split('\n').slice(0, 22).map((l, i) => String(i + 1).padStart(3) + ' | ' + l).join('\n'));

