  let s = fs.readFileSync(file, 'utf8');
  if (s.includes('load_frontend_utils.mjs')) { console.log('  跳过(已有 import): ' + f); continue; }
  const lines = s.split('\n');
  let last = -1;
  lines.forEach((l, i) => { if (/^import /.test(l)) last = i; });
  if (last < 0) { console.error('找不到 import 区: ' + file); process.exit(1); }
  lines.splice(last + 1, 0, `import { loadFrontendUtils } from './load_frontend_utils.mjs';`);
  fs.writeFileSync(file + '.tmp', lines.join('\n'));
  fs.renameSync(file + '.tmp', file);
  console.log('  应用: ' + f + ' 加 loader import');
}
console.log('完成');

