import fs from 'node:fs';

const R = 'r-scripts/nonrandom_permanova.R';
let s = fs.readFileSync(R, 'utf8');
const out = [];
const sub = (from, to, label) => {
  if (!s.includes(from)) { out.push('未匹配: ' + label); return; }
  if (s.split(from).length > 2) { out.push('锚点不唯一: ' + label); return; }
  s = s.replace(from, to);
  out.push('应用: ' + label);
};

// ---------------------------------------------------------------- 1) 引擎函数
sub(
`permanova_f_from_dist <- function(d2, assign) {`,
`# 距离阵 -> Gower 双中心化 -> 特征分解，取正特征值轴当响应矩阵。
# 这就是 vegan::capscale 的内部做法：在这组坐标上做普通线性投影，得到的 SS/F
# 与距离基 PERMANOVA 完全一致，且天然支持连续协变量（旧实现不支持，见 main 里注释）。
make_pcoa_basis <- function(d2, tol_ratio = 1e-9) {
  n <- nrow(d2)
  J <- diag(n) - 1 / n
  G <- -0.5 * J %*% d2 %*% J
  G <- (G + t(G)) / 2                                    # 消除浮点不对称
  ev <- eigen(G, symmetric = TRUE)
  keep <- ev$values > max(1e-12, max(ev$values) * tol_ratio)
  lam <- ev$values[keep]
  list(Y = ev$vectors[, keep, drop = FALSE] %*% diag(sqrt(lam), nrow = length(lam)),
       lambda = lam, n_neg = as.integer(sum(ev$values < -1e-12)))
}

permanova_f_from_dist <- function(d2, assign) {`,
  '插入 make_pcoa_basis'
);

// ------------------------------------------------- 2) 删掉「连续变量转因子」假处理
sub(
`  # 分类变量转因子（连续变量保留原样）
  for (v in terms) {
    if (!is.numeric(sample_data[[v]])) sample_data[[v]] <- factor(sample_data[[v]])
  }

`,
`  # 因子/连续变量的编码统一放到下面的 design_cols 里处理
`,
  '删除旧的因子转换补丁'
);

// ---------------------------------------------------------- 3) 观测值 + 置换核心
sub(
`  # ---------------- 观测值：多因素逐次 ANOVA（type-II 风格）----------------
  # 设计矩阵（去掉截距），按术语分块
  model_df <- sample_data[, terms, drop = FALSE]
  design <- model.matrix(~ . - 1, data = model_df)
  col_groups <- attr(design, "assign")

  obs_table <- list()
  for (ti in seq_along(terms)) {
    cols_i <- which(col_groups == ti)
    assign_all <- design[, cols_i, drop = FALSE]
    # 组间离散度：用最近邻划分（对连续协变量按其数值分位分箱）
    if (length(cols_i) == 1 && is.numeric(model_df[[terms[ti]]]) && length(unique(assign_all)) > 6) {
      grp <- cut(assign_all, breaks = 4, labels = FALSE)
    } else {
      grp <- as.integer(factor(apply(assign_all, 1, paste, collapse = "_")))
    }
    res <- permanova_f_from_dist(d2, grp)
    obs_table[[length(obs_table) + 1]] <- list(
      term = terms[ti], df = length(unique(grp)) - 1,
      F_model = res[1], R2 = res[2], R2_within = res[3],
      n_levels = length(unique(grp))
    )
  }

  # 全局模型（所有术语合并）
  full_grp <- as.integer(factor(apply(design, 1, paste, collapse = "_")))
  obs_global <- permanova_f_from_dist(d2, full_grp)

  # ---------------- 受限置换零分布 ----------------
  run_perm <- function(block_vec) {
    fs <- numeric(permutations)
    for (i in seq_len(permutations)) {
      pgrp <- if (is.null(block_vec)) sample(full_grp) else permute_within_blocks(full_grp, block_vec)
      fs[i] <- permanova_f_from_dist(d2, pgrp)[1]
    }
    fs
  }`,
`  # ---------------- 观测值：距离基线性模型（等价 capscale + anova）----------------
  # 旧实现按「设计列的唯一组合」给样本分组，那只对纯因子设计成立。
  # 公式里一旦出现连续变量（用户写的 pH，或 controlCoverage 注入的 .coverage），
  # 唯一组合数≈n，残差自由度被吃光，F 完全失真 —— 实测能把 group 的 F 从 19.3 压到 1.5，
  # 而 pH 与区组的相关只有 0.011，本来根本不该影响 group。现在改为：
  #   距离阵 -> PCoA 正轴(响应矩阵 Y) -> 线性投影求 SS -> F。
  # 因子与连续协变量共用同一套分解，置换也只移动「主术语列与 Y 行的配对」。
  model_df <- sample_data[, terms, drop = FALSE]
  basis <- make_pcoa_basis(d2)
  Y <- basis$Y
  ss_tot <- sum(Y^2)                                  # = Σ_{i<j} d²_ij / n

  design_cols <- lapply(terms, function(v) {
    x <- sample_data[[v]]
    if (is.numeric(x)) matrix(as.numeric(x), ncol = 1, dimnames = list(NULL, v))
    else as.matrix(model.matrix(~ factor(x) - 1))
  })
  names(design_cols) <- terms

  rss_of <- function(Xm) {
    if (is.null(Xm) || ncol(Xm) == 0) return(ss_tot)
    sum(qr.resid(qr(Xm), Y)^2)
  }
  rank_of <- function(Xm) if (is.null(Xm) || ncol(Xm) == 0) 0L else qr(Xm)$rank
  cbind1 <- function(...) {
    m <- do.call(cbind, Filter(function(z) !is.null(z) && ncol(z) > 0, list(...)))
    if (is.null(m)) matrix(1, nrow = n, ncol = 1) else cbind(`(Intercept)` = 1, m)
  }
  f_stat2 <- function(ss_extra, df_extra, rss, df_resid) {
    if (is.na(ss_extra) || df_extra < 1 || df_resid < 1 || rss <= 0) return(NA_real_)
    (ss_extra / df_extra) / (rss / df_resid)
  }

  Xfull <- cbind1(design_cols)
  rank_full <- rank_of(Xfull)
  if (rank_full >= n) {
    stop(sprintf("设计矩阵饱和（秩 %d ≥ 样本数 %d）：请减少术语、合并水平，或改用分层置换", rank_full, n))
  }
  rss_full <- rss_of(Xfull)
  F_full_model <- f_stat2(ss_tot - rss_full, rank_full - 1, rss_full, n - rank_full)
  R2_full <- if (ss_tot > 0) (ss_tot - rss_full) / ss_tot else NA_real_

  # 逐术语 type-II：先把其他术语入模，再看本术语的额外解释量（与术语顺序无关）
  obs_table <- list()
  for (ti in seq_along(terms)) {
    Xi <- design_cols[[ti]]
    Xother <- if (length(terms) > 1) cbind1(design_cols[-ti]) else matrix(1, nrow = n, ncol = 1)
    Xboth <- cbind(Xother, Xi)
    rk_other <- rank_of(Xother)
    rk_both <- rank_of(Xboth)
    rss_both <- rss_of(Xboth)
    ss_extra <- rss_of(Xother) - rss_both
    df_e <- rk_both - rk_other
    obs_table[[length(obs_table) + 1]] <- list(
      term = terms[ti], df = as.integer(max(0, df_e)),
      F_model = f_stat2(ss_extra, df_e, rss_both, n - rk_both),
      R2 = if (ss_tot > 0 && !is.na(ss_extra)) ss_extra / ss_tot else NA_real_,
      R2_within = NA_real_,
      n_levels = as.integer(length(unique(as.character(sample_data[[terms[ti]]]))))
    )
  }

  # 检验统计量 = 主术语（公式第一项）控制其余术语后的 type-II F。
  # 单项公式时它就是全模型 F，与 vegan::adonis2(..., by = NULL) 完全一致。
  primary <- 1
  tested_term <- terms[primary]
  X_primary <- design_cols[[primary]]
  X_cond <- if (length(terms) > 1) cbind1(design_cols[-primary]) else matrix(1, nrow = n, ncol = 1)
  rk_cond <- rank_of(X_cond)
  rss_cond <- rss_of(X_cond)
  F_test <- f_stat2(rss_cond - rss_of(cbind(X_cond, X_primary)),
                    rank_of(cbind(X_cond, X_primary)) - rk_cond,
                    rss_of(cbind(X_cond, X_primary)),
                    n - rank_of(cbind(X_cond, X_primary)))
  R2_test <- (rss_cond - rss_of(cbind(X_cond, X_primary))) / ss_tot
  obs_global <- c(F_test, R2_test, 1 - R2_test)

  # ---------------- 受限置换零分布 ----------------
  # 只置换主术语的标签（其余术语/协变量与样本的配对保持不变），这正是
  # 「在允许的范围内交换处理标签」的含义；区组/空间限制体现在 idx 的生成上。
  f_of_perm <- function(idx) {
    Xp <- cbind(X_cond, X_primary[idx, , drop = FALSE])
    rk <- rank_of(Xp)
    rss <- rss_of(Xp)
    f_stat2(rss_cond - rss, rk - rk_cond, rss, n - rk)
  }
  run_perm <- function(block_vec) {
    fs <- rep(NA_real_, permutations)
    for (i in seq_len(permutations)) {
      idx <- if (is.null(block_vec)) sample.int(n) else permute_within_blocks(seq_len(n), block_vec)
      fs[i] <- f_of_perm(idx)
    }
    fs
  }`,
  '观测值与置换改用距离基线性模型引擎'
);

// ------------------------------------------------------------ 4) PCoA 复用 basis
sub(
`  pcoa <- tryCatch({
    pc <- vegan::wcmdscale(dmat, k = 2, eig = TRUE)
    sc <- pc$points[, 1:2, drop = FALSE]
    ev <- pc$eig[1:2]
    tot <- sum(pmax(pc$eig, 0))
    list(`,
`  pcoa <- tryCatch({
    # 直接复用上面已经算好的特征分解，不再 wcmdscale 第二遍
    tot <- sum(basis$lambda)
    k <- min(2, length(basis$lambda))
    sc <- basis$Y[, seq_len(k), drop = FALSE]
    ev <- basis$lambda[seq_len(k)]
    list(`,
  'PCoA 复用 basis'
);
sub(
`      x = as.numeric(sc[, 1]), y = as.numeric(sc[, 2]),`,
`      x = as.numeric(sc[, 1]), y = if (k >= 2) as.numeric(sc[, 2]) as.numeric(rep(0, n)),`,
  'PCoA 单轴保护'
);

// ------------------------------------------------------ 5) 输出补上口径说明
sub(
`    observed = list(
      F_model = obs_global[1],`,
`    observed = list(
      F_model = obs_global[1],
      tested_term = tested_term,
      F_full_model = F_full_model,
      R2_full = R2_full,`,
  '输出标注检验的术语'
);
sub(
`      scheme = plan$scheme,
      requested = permutations,`,
`      scheme = plan$scheme,
      tested_term = tested_term,
      note_scheme = paste0("置换对象：公式首项 ", tested_term, " 的标签（其余术语与样本配对保持不变）"),
      requested = permutations,`,
  '置换说明'
);

fs.writeFileSync(R + '.tmp', s);
fs.renameSync(R + '.tmp', R);
console.log(out.join('\n'));
process.exit(out.some((l) => /未匹配|不唯一/.test(l)) ? 1 : 0);

