/**
 * 从 PERMANOVA_Med.vue 抽出共享样式表，供三个新界面复用。
 *
 * 为什么脚本抽取而不是手抄：新界面要求「样式与现有界面完全一致」，手抄 870 行
 * CSS 必然漂移（少一条 hover、改一个圆角都发现不了）。脚本可重跑，
 * 源仍是 PERMANOVA_Med.vue 的 <style scoped>，改样式后重跑本脚本即可同步。
 *
 *   node r-scripts/tools/extract_ra_styles.mjs
 */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '../..');
const SRC = path.join(ROOT, 'frontend/src/views/r-analysis/PERMANOVA_Med.vue');
const OUT_DIR = path.join(ROOT, 'frontend/src/components/r-analysis');
const OUT = path.join(OUT_DIR, 'r-analysis.css');

const vue = fs.readFileSync(SRC, 'utf8');
const m = vue.match(/<style scoped>([\s\S]*?)<\/style>/);
if (!m) { console.error('没找到 <style scoped> 块'); process.exit(1); }
let css = m[1].trim();

// 去掉 med 专有命名，改成中性的共享命名（视觉不变，语义不再误导）
const RENAMES = [
  ['.permanova-med-container', '.ra-shell'],
  ['.med-headline-card', '.headline-card'],
  ['.med-headline-left', '.headline-left'],
  ['.med-headline-right', '.headline-right'],
  ['.med-p-big', '.headline-p'],
  ['.med-p-caption', '.headline-caption'],
  ['.med-interp', '.headline-interp'],
  ['.med-sub', '.headline-sub'],
  ['.mediator-effects-card', '.result-card'],
  ['.med-data-note', '.template-note'],
  ['.med-data-current', '.template-current']
];
for (const [a, b] of RENAMES) css = css.split(a).join(b);

/**
 * 给每条规则的选择器加上 `.ra-shell ` 前缀（scoped 样式是组件内隔离的，
 * 这里是全局 CSS，不加前缀会污染 Home / PERMANOVA 等既有页面）。
 */
function prefixSelector(sel) {
  return sel
    .split(',')
    .map((s) => {
      const t = s.trim();
      if (!t) return t;
      if (t === '.ra-shell') return t;                       // 容器自身规则不加前缀
      if (t.startsWith('.ra-shell')) return t;
      if (t.startsWith('from ') || t.startsWith('to ') || /^(\/\*|\d|%)/.test(t)) return t;  // keyframes
      return '.ra-shell ' + t;
    })
    .join(', ');
}

// 逐字符扫描：普通规则与 @media 内的嵌套规则都要处理
let out = '';
let i = 0;
const n = css.length;
const atDepth = [];
while (i < n) {
  const brace = css.indexOf('{', i);
  if (brace < 0) { out += css.slice(i); break; }
  const head = css.slice(i, brace);
  // 找到与本规则配对的右括号
  let depth = 1, j = brace + 1;
  while (j < n && depth > 0) {
    if (css[j] === '{') depth++;
    else if (css[j] === '}') depth--;
    j++;
  }
  const body = css.slice(brace + 1, j - 1);
  const trimmedHead = head.trim();
  if (trimmedHead.startsWith('@media') || trimmedHead.startsWith('@supports')) {
    // 递归处理内部规则
    let inner = '', k = 0;
    while (k < body.length) {
      const b2 = body.indexOf('{', k);
      if (b2 < 0) { inner += body.slice(k); break; }
      let d2 = 1, j2 = b2 + 1;
      while (j2 < body.length && d2 > 0) { if (body[j2] === '{') d2++; else if (body[j2] === '}') d2--; j2++; }
      inner += prefixSelector(body.slice(k, b2).trim()) + ' {' + body.slice(b2 + 1, j2 - 1) + '}';
      k = j2;
    }
    out += head + trimmedHead + ' {\n' + inner + '\n}\n';
  } else if (trimmedHead.startsWith('@keyframes') || trimmedHead.startsWith('@-webkit-keyframes')) {
    out += head + trimmedHead + ' {' + body + '}\n';                      // 帧内选择器不能加前缀
  } else if (/^[A-Za-z.#][^{}]*$/.test(trimmedHead.replace(/\s+/g, ' '))) {
    out += head.replace(/[^\s,].*$/, '') + prefixSelector(trimmedHead) + ' {' + body + '}\n';
  } else {
    out += head + body;                                                    // 注释等原样保留
  }
  i = j;
}

const banner = `/**
 * R 分析界面共享样式
 * ---------------------------------------------------------------
 * 本文件由 r-scripts/tools/extract_ra_styles.mjs 从
 * frontend/src/views/r-analysis/PERMANOVA_Med.vue 的 <style scoped> 自动生成，
 * 目的：让新增的分析界面（Non-random PERMANOVA / GMR⁴ / Bayesian ERA）
 * 与既有界面像素级一致，同时避免把 870 行 CSS 复制三份各自漂移。
 *
 * 所有选择器都限定在 .ra-shell 之内，不会泄漏到 Home / PERMANOVA 等页面。
 * 需要调整样式时：改 PERMANOVA_Med.vue 后重跑抽取脚本，不要直接编辑本文件。
 */
