const stripComments = (t) => t.replace(/\/\*[\s\S]*?\*\//g, '');

function prefixSelector(sel) {
  return sel.split(',').map((s) => {
    const t = s.trim();
    if (!t) return t;
    if (t === '.ra-shell' || t.startsWith('.ra-shell')) return t;   // 容器自身规则不套娃
