/**
 * Non-random PERMANOVA 图表配置生成（纯函数，便于 node 侧单测）
 * 输入 = r-scripts/nonrandom_permanova.R 的 chart_data，输出 = ECharts option
 *
 * 设计原则（与 medCharts.js 一致）：
 *   1. 图上每个数值都必须来自 R 的真实计算，不允许写死占位数据；
 *   2. NaN/Inf 一律转成 null，避免 ECharts 把它们画成「看不见的点」（沉默失败）；
 *   3. 本模块的核心信息是「同一个 F，在两种零分布下的位置不同」，
 *      所以第一张图必须把两条零分布叠在一起画，而不是各画一张。
 */

/** 等宽分箱；返回中心点与计数（计数用整数，tooltip 里可还原真实频数） */
export function histogram(values, bins = 30) {
  const v = (values || []).map(Number).filter((x) => Number.isFinite(x));
  if (!v.length) return { centers: [], counts: [], min: 0, max: 0, n: 0 };
  const min = Math.min(...v);
  const max = Math.max(...v);
  const span = max - min || Math.abs(max) || 1;
  const width = span / bins;
  const counts = new Array(bins).fill(0);
  for (const x of v) {
    const k = Math.min(bins - 1, Math.floor((x - min) / width));
    counts[k] += 1;
  }
  const centers = counts.map((_, i) => Number((min + width * (i + 0.5)).toFixed(6)));
  return { centers, counts, min, max, n: v.length };
}

/**
 * ① 零分布对比：自由置换 vs 受限置换，叠加观测 F 竖线
 * 这是本功能的主图：两条分布错开多少，p 值为什么会翻盘，一眼就能看出来。
 */
export function buildNullCompareChart(cd, { fmt, fmtP }) {
  const observed = Number(cd?.null?.observed) || 0;
  const free = histogram(cd?.null_free?.values, 32);
  const con = histogram(cd?.null?.values, 32);
  const bins = 32;
  // 两条分布必须共用同一套横轴刻度，否则「谁更靠左」会被读成画图错觉
  const lo = Math.min(free.min, con.min, observed);
  const hi = Math.max(free.max, con.max, observed);
  const span = hi - lo || 1;
  const axis = Array.from({ length: bins }, (_, i) => Number((lo + (span * (i + 0.5)) / bins).toFixed(4)));
  const bucket = (h) => {
    if (!h.counts.length) return new Array(bins).fill(0);
    const out = new Array(bins).fill(0);
    h.centers.forEach((c, i) => {
      const k = Math.max(0, Math.min(bins - 1, Math.floor(((c - lo) / span) * bins)));
      out[k] += h.counts[i];
    });
    return out;
  };
  const freeCnt = bucket(free);
  const conCnt = bucket(con);
  const hasFree = !!cd?.null_free;

  const series = [];
  if (hasFree) {
    series.push({
      name: '自由置换零分布',
      type: 'bar',
      data: freeCnt,
      itemStyle: { color: 'rgba(245, 108, 108, 0.55)', borderColor: '#f56c6c', borderWidth: 1 },
      barGap: '-100%'
    });
  }
  series.push({
    name: `受限置换零分布（${cd?.null?.scheme || 'stratified'}）`,
    type: 'bar',
    data: conCnt,
    itemStyle: { color: 'rgba(64, 158, 255, 0.75)', borderColor: '#409eff', borderWidth: 1 },
    markLine: {
      symbol: 'none',
      lineStyle: { color: '#303133', width: 2.5, type: 'solid' },
      label: { formatter: `观测 F = ${fmt(observed, 3)}`, position: 'insideEndTop', fontSize: 12, fontWeight: 600 },
      data: [{ xAxis: Number(observed.toFixed(4)) }]
    }
  });

  return {
    title: {
      text: '同一个 F，两种零分布',
      subtext: hasFree
        ? `p(自由) = ${fmtP(cd.null_free.p)} ｜ p(受限) = ${fmtP(cd.null.p)} —— 差异完全来自零分布允许哪些排列`
        : `scheme=free：本次只有一种置换方案，p = ${fmtP(cd?.null?.p)}`,
      left: 'center',
      textStyle: { fontSize: 15 },
      subtextStyle: { fontSize: 12 }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (ps) => {
        const arr = Array.isArray(ps) ? ps : [ps];
        const lines = [`F ≈ ${arr[0]?.axisValue}`];
        arr.forEach((p) => lines.push(`${p.marker}${p.seriesName}：${p.data} 次`));
        return lines.join('<br/>');
      }
    },
    legend: { bottom: 4, data: series.map((s) => s.name) },
    grid: { left: 60, right: 30, top: 86, bottom: 56 },
    xAxis: { type: 'category', data: axis, name: '置换 F 统计量', nameLocation: 'middle', nameGap: 28 },
    yAxis: { type: 'value', name: '频次' },
    series
  };
}

/**
 * ② 结论对比：p_free / p_constrained 双条 + 0.05 阈值线
 * 用 -log10(p) 会让「显著/不显著」的边界不直观，这里直接用 p 并画阈值线。
 */
export function buildPComparisonChart(cd, { fmt, fmtP }) {
  const rows = cd?.comparison || [];
  const cats = rows.map((r) => (r.scheme === 'free' ? '自由置换（所有排列）' : `受限置换（${r.scheme}）`));
  const vals = rows.map((r) => (Number.isFinite(Number(r.p)) ? Number(r.p) : null));
  const colors = vals.map((p) => (p === null ? '#909399' : p < 0.05 ? '#67c23a' : '#e6a23c'));
  const observed = rows.length ? Number(rows[0].F) : null;

  return {
    title: {
      text: '置换方案对结论的影响',
      subtext: `观测 F = ${fmt(observed, 3)}（两种方案用的是同一个 F，只有零分布不同）`,
      left: 'center',
      textStyle: { fontSize: 15 },
      subtextStyle: { fontSize: 12 }
    },
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (ps) => {
        const arr = Array.isArray(ps) ? ps : [ps];
        return arr
          .map((p) => `${p.marker}${p.name}：p = ${fmtP(p.data)}${p.data < 0.05 ? '（显著）' : '（不显著）'}`)
          .join('<br/>');
      }
    },
    grid: { left: 70, right: 40, top: 80, bottom: 50 },
    xAxis: { type: 'category', data: cats },
    yAxis: { type: 'value', name: 'p 值', min: 0, max: 1 },
    series: [
      {
        type: 'bar',
        barWidth: 90,
        data: vals.map((v, i) => ({ value: v, itemStyle: { color: colors[i] } })),
        label: { show: true, position: 'top', formatter: (x) => fmtP(x.data), fontWeight: 600 },
        markLine: {
          symbol: 'none',
          lineStyle: { color: '#f56c6c', type: 'dashed', width: 2 },
          label: { formatter: 'α = 0.05', position: 'end', color: '#f56c6c' },
          data: [{ yAxis: 0.05 }]
        }
      }
    ]
  };
}

const STRATA_SYMBOLS = ['circle', 'rect', 'diamond', 'triangle', 'roundRect', 'pin', 'arrow', 'none'];

/**
 * ③ PCoA 散点：颜色 = 分组，形状 = 区组
 * 形状编码区组是刻意的：受限置换只在区组内交换标签，图上要能看出
 * 「同一区组里既有 A 又有 B」才说明设计平衡。
 */
export function buildPcoaChart(cd, { fmt }) {
  const p = cd?.pcoa || {};
  const xs = p.x || [];
  const ys = p.y || [];
  const groups = p.group || [];
  const strata = p.strata || [];
  const labels = p.labels || [];
  const gvars = p.var_explained || [];

  const glevels = [...new Set(groups.map(String))];
  const slevels = [...new Set(strata.map(String))];
  const hasStrata = slevels.length > 1 || (slevels.length === 1 && slevels[0] !== 'NA');

  const series = glevels.map((g, gi) => ({
    name: g,
    type: 'scatter',
    symbolSize: 11,
    itemStyle: { opacity: 0.85, borderColor: '#fff', borderWidth: 1 },
    data: xs
      .map((x, i) => ({
        value: [x, ys[i]],
        symbol: hasStrata ? STRATA_SYMBOLS[slevels.indexOf(String(strata[i])) % STRATA_SYMBOLS.length] : 'circle',
        label: labels[i],
        strata: String(strata[i])
      }))
      .filter((_, i) => String(groups[i]) === g)
  }));

  return {
    title: {
      text: 'PCoA（Bray-Curtis / 距离基主坐标）',
      subtext: `颜色=分组，形状=区组；PC1 ${fmt((gvars[0] || 0) * 100, 2)}%` +
        (gvars.length > 1 ? `，PC2 ${fmt((gvars[1] || 0) * 100, 2)}%` : ''),
      left: 'center',
      textStyle: { fontSize: 15 },
      subtextStyle: { fontSize: 12 }
    },
    tooltip: {
      formatter: (pp) =>
        `${pp.data?.label || pp.seriesName}<br/>区组：${pp.data?.strata}<br/>PC1 = ${fmt(pp.value[0], 4)}<br/>PC2 = ${fmt(pp.value[1], 4)}`
    },
    legend: { bottom: 4, data: glevels },
    grid: { left: 66, right: 30, top: 78, bottom: 56 },
    xAxis: { type: 'value', name: `PC1 (${fmt((gvars[0] || 0) * 100, 1)}%)`, nameLocation: 'middle', nameGap: 26, scale: true },
    yAxis: { type: 'value', name: `PC2 (${fmt((gvars[1] || 0) * 100, 1)}%)`, scale: true },
    series
  };
}

/** ④ 逐术语解释量：R² 柱 + F 折线（双轴），多术语公式时用来核对边际检验 */
export function buildVarianceChart(cd, { fmt }) {
  const rows = cd?.variance || [];
  const cats = rows.map((r) => r.term);
  const r2 = rows.map((r) => (Number.isFinite(Number(r.R2)) ? Number(r.R2) : null));
  const fs = rows.map((r) => (Number.isFinite(Number(r.F)) ? Number(r.F) : null));
  return {
    title: {
      text: '逐术语解释量（边际检验）',
      subtext: '多术语时各行为独立边际检验，R² 不可相加；df 标注在柱顶',
      left: 'center',
      textStyle: { fontSize: 15 },
      subtextStyle: { fontSize: 12 }
    },
    tooltip: {
      trigger: 'axis',
      formatter: (ps) => {
        const arr = Array.isArray(ps) ? ps : [ps];
        const i = arr[0]?.dataIndex ?? 0;
        const row = rows[i] || {};
        return [
          `${row.term}`,
          `R² = ${fmt(row.R2, 4)}`,
          `F = ${fmt(row.F, 3)}（df = ${row.df}，水平数 = ${row.n_levels ?? '-'}）`
        ].join('<br/>');
      }
    },
    legend: { bottom: 4 },
    grid: { left: 60, right: 60, top: 78, bottom: 56 },
    xAxis: { type: 'category', data: cats },
    yAxis: [
      { type: 'value', name: 'R²', min: 0 },
      { type: 'value', name: 'F', min: 0, splitLine: { show: false } }
    ],
    series: [
      {
        name: 'R²',
        type: 'bar',
        data: r2,
        barWidth: 46,
        itemStyle: { color: '#409eff' },
        label: { show: true, position: 'top', formatter: (x) => `df ${rows[x.dataIndex]?.df ?? '-'}` }
      },
      { name: 'F', type: 'line', yAxisIndex: 1, data: fs, itemStyle: { color: '#e6a23c' }, symbolSize: 9, lineStyle: { width: 2 } }
    ]
  };
}

export const NR_CHART_BUILDERS = {
  null: buildNullCompareChart,
  pcompare: buildPComparisonChart,
  pcoa: buildPcoaChart,
  variance: buildVarianceChart
};

export const NR_CHART_TABS = [
  { id: 'null', name: '零分布对比' },
  { id: 'pcompare', name: '结论对比' },
  { id: 'pcoa', name: 'PCoA 排序' },
  { id: 'variance', name: '解释量分解' }
];

#!/usr/bin/env node
/**
 * Non-random PERMANOVA 图表配置单测
 * ---------------------------------------------------------------
 * 数据来源是**真跑 R** 得到的 chart_data（不是手搓的假 option）：
 * 图表代码最常见的 bug 是「字段名对不上」，用手工构造的输入自测等于自欺。
 *
 *   node r-scripts/tools/test_nr_charts.mjs
 *   RSCRIPT=... node r-scripts/tools/test_nr_charts.mjs     # 换 R 版本 A/B
 */
import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';
import { fileURLToPath } from 'url';
import { loadFrontendUtils } from './load_frontend_utils.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '../..');
const SCRIPT = path.join(ROOT, 'r-scripts/nonrandom_permanova.R');
const RSCRIPT = process.env.RSCRIPT || path.join(ROOT, 'r-portable/bin/Rscript.exe');
const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'nrcharts-'));

const { nonrandomTemplates: nrt, nrCharts: nc, format: fmtMod } =
  await loadFrontendUtils(['nonrandomTemplates', 'nrCharts', 'format']);
const F = fmtMod.makeFormatters();

let pass = 0, fail = 0;
const fails = [];
const t = (name, cond, extra = '') => {
  if (cond) { pass++; }
  else { fail++; fails.push(name + (extra ? ` —— ${extra}` : '')); }
};
const finite = (v) => typeof v === 'number' && Number.isFinite(v);
// ECharts 会把 NaN 画成「不存在的点」，所以图上不允许出现 NaN（null 是允许的断点）
const noNaN = (o, label) => {
  const s = JSON.stringify(o);
  t(label + ' 无 NaN', !/NaN/.test(s), s.slice(0, 120));
};
const deepNumbers = (o) => {
  const out = [];
  const walk = (v) => {
    if (typeof v === 'number') out.push(v);
    else if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') Object.values(v).forEach(walk);
  };
  walk(o);
  return out;
};

const runR = (spec, tag) => {
  const built = nrt.buildNonrandomTemplateData(spec);
  const inPath = path.join(TMP, `${tag}.json`);
  fs.writeFileSync(inPath, JSON.stringify(built.payload));
  execFileSync(RSCRIPT, [SCRIPT, inPath, inPath + '.out', inPath + '.err'], { stdio: 'pipe', timeout: 180000 });
  const json = JSON.parse(fs.readFileSync(inPath + '.out', 'utf8'));
  return { built, json };
};

// 三个有代表性的设计：假阳性案例（两条零分布分得很开）、双显著案例、纯自由置换案例
const CASES = ['confoundedBlock', 'balancedBlock', 'freeOnly', 'spatialField'];
const results = [];
for (const id of CASES) {
  const item = nrt.NR_TEMPLATE_MAP[id];
  if (!item) { t(`${id} 模板存在`, false); continue; }
  try {
    const r = runR(item.spec, id);
    results.push({ id, ...r });
    t(`${id} R 运行成功`, r.json.success === true);
  } catch (e) {
    t(`${id} R 运行成功`, false, String(e.message).slice(0, 80));
  }
}

// ---------------------------------------------------------- histogram 单元检查
{
  const h = nc.histogram([1, 1, 2, 2, 3, 3, 4, 4], 4);
  t('histogram 计数守恒', h.counts.reduce((a, b) => a + b, 0) === 8);
  t('histogram 范围正确', h.min === 1 && h.max === 4);
  t('histogram 空输入不炸', nc.histogram([], 10).counts.length === 0 && nc.histogram(undefined, 10).n === 0);
  const single = nc.histogram([5, 5, 5], 8);
  t('histogram 常量输入（span=0）不产生 NaN', deepNumbers(single).every(Number.isFinite), JSON.stringify(single.centers));
  t('histogram 过滤 NaN', nc.histogram([1, NaN, 2, undefined, 3], 3).n === 3);
}

// ---------------------------------------------------------- 每张图的断言
for (const { id, json, built } of results) {
  const cd = json.chart_data;
  const n = json.model.n_samples;
  const scheme = json.permutation.scheme;
  const isFree = scheme === 'free';

  t(`${id}: chart_data 齐全`, cd && cd.null && cd.pcoa && cd.variance && cd.comparison,
    cd ? Object.keys(cd).join(',') : 'undefined');
  if (!cd || !cd.null) continue;

  // ---- ① 零分布对比 ----
  const o1 = nc.buildNullCompareChart(cd, F);
  noNaN(o1, `${id}/零分布`);
  const s1 = o1.series;
  t(`${id}: 零分布图系列数正确`, s1.length === (isFree ? 1 : 2), `${s1.length} vs ${isFree ? 1 : 2}`);
  const sumBins = (s) => s.data.reduce((a, b) => a + (Number(b) || 0), 0);
  const conS = s1[s1.length - 1];
  t(`${id}: 受限直方图频数 = 实际点数`, sumBins(conS) === cd.null.values.length,
    `${sumBins(conS)} vs ${cd.null.values.length}`);
  if (!isFree) {
    t(`${id}: 自由直方图频数 = 实际点数`, sumBins(s1[0]) === cd.null_free.values.length);
    t(`${id}: 两条分布横轴共用同一刻度`, s1[0].data.length === o1.xAxis.data.length);
    t(`${id}: 自由零分布确实更长尾（假阳性来源可视化）`,
      Math.max(...cd.null_free.values) > Math.max(...cd.null.values) * 0.5,
      `free max=${Math.max(...cd.null_free.values).toFixed(2)}, con max=${Math.max(...cd.null.values).toFixed(2)}`);
  }
  const ml = conS.markLine?.data?.[0]?.xAxis;
  t(`${id}: 观测 F 竖线位置 = R 给的 F`, Math.abs(ml - cd.null.observed) < 1e-3, `${ml} vs ${cd.null.observed}`);
  t(`${id}: 直方图横轴单调递增`, o1.xAxis.data.every((v, i, a) => i === 0 || v > a[i - 1]));

  // ---- ② 结论对比 ----
  const o2 = nc.buildPComparisonChart(cd, F);
  noNaN(o2, `${id}/结论对比`);
  const vals = o2.series[0].data.map((d) => d.value);
  t(`${id}: p 图两项`, vals.length === 2);
  t(`${id}: p 值与 R 输出一致`,
    Math.abs(vals[0] - json.observed.p_free) < 1e-12 && Math.abs(vals[1] - json.observed.p_constrained) < 1e-12);
  t(`${id}: 颜色按 α=0.05 着色`,
    o2.series[0].data.every((d, i) => d.itemStyle.color === (d.value < 0.05 ? '#67c23a' : '#e6a23c')));
  t(`${id}: 阈值线画在 0.05`, o2.series[0].markLine.data[0].yAxis === 0.05);
  t(`${id}: p 轴固定 0..1`, o2.yAxis.min === 0 && o2.yAxis.max === 1);

  // ---- ③ PCoA ----
  const o3 = nc.buildPcoaChart(cd, F);
  noNaN(o3, `${id}/PCoA`);
  const pts = o3.series.reduce((s, x) => s + x.data.length, 0);
  t(`${id}: PCoA 点数 = 样本数`, pts === n, `${pts} vs ${n}`);
  t(`${id}: 每个点都有坐标且有限`, o3.series.every((s) => s.data.every((p) => finite(p.value[0]) && finite(p.value[1]))));
  t(`${id}: 系列数 = 分组数`, o3.series.length === new Set(cd.pcoa.group.map(String)).size);
  t(`${id}: 点带样本名与区组`, o3.series.every((s) => s.data.every((p) => p.label && p.strata)));
  if (!isFree) {
    const symbols = new Set(o3.series.flatMap((s) => s.data.map((p) => p.symbol)));
    t(`${id}: 区组用不同形状区分`, symbols.size >= Math.min(2, new Set(cd.pcoa.strata).size), [...symbols].join(','));
  }

  // ---- ④ 解释量 ----
  const o4 = nc.buildVarianceChart(cd, F);
  noNaN(o4, `${id}/解释量`);
  t(`${id}: 术语数与 anova_table 一致`, o4.xAxis.data.length === json.anova_table.length);
  t(`${id}: R² 来自 R`, o4.series[0].data.every((v, i) => v === null || Math.abs(v - json.anova_table[i].R2) < 1e-12));
  t(`${id}: F 来自 R`, o4.series[1].data.every((v, i) => v === null || Math.abs(v - json.anova_table[i].F_model) < 1e-12));
  t(`${id}: R² ∈ [0,1]`, deepNumbers({ a: o4.series[0].data }).filter(Number.isFinite).every((v) => v >= 0 && v <= 1));

  // ---- 标签页与构建器一一对应（视图按 tab 找 builder，缺了就白屏） ----
  for (const tab of nc.NR_CHART_TABS) {
    t(`${id}: tab ${tab.id} 有对应 builder`, typeof nc.NR_CHART_BUILDERS[tab.id] === 'function');
  }
}

// -------------------------------------------------- 旗舰案例的教学效果必须可见
{
  const flagship = results.find((r) => r.id === 'confoundedBlock');
  if (flagship) {
    const cd = flagship.json.chart_data;
    t('旗舰案例：两条零分布画出来分得开',
      cd.null_free && cd.null && Math.max(...cd.null.values) < Math.max(...cd.null_free.values),
      `受限最大 F=${cd.null ? Math.max(...cd.null.values).toFixed(2) : '-'}，自由最大 F=${cd.null_free ? Math.max(...cd.null_free.values).toFixed(2) : '-'}`);
    const o = nc.buildNullCompareChart(cd, F);
    t('旗舰案例：副标题写明两个 p', /p\(自由\)[\s\S]*p\(受限\)/.test(o.title.subtext), o.title.subtext);
    t('旗舰案例：受限 p 不显著、自由 p 显著',
      cd.null.p >= 0.05 && cd.null_free.p < 0.05);
  }
}

console.log(`\nNon-random PERMANOVA 图表测试：${CASES.join(', ')}`);
console.log(`──────── ${pass} 通过 / ${fail} 失败 ────────`);
if (fails.length) {
  console.log('\n失败项:');
  fails.forEach((f) => console.log('  - ' + f));
}
fs.rmSync(TMP, { recursive: true, force: true });
process.exit(fail ? 1 : 0);

