/** 返回五项校验的布尔数组（canRun/runHint 共用，避免两处逻辑漂移） */
validate() {
  const c = inspectMatrix(this.form.communityStr);
  this.v.community = c.ok ? { ok: true, n: c.n, p: c.p } : { ok: false, error: c.error, n: 0, p: 0 };

  const s = this.form.sampleStr.trim()
    ? inspectSampleTable(this.form.sampleStr, c.ok ? c.n : null)
    : { ok: false, error: '等待输入' };
  this.v.sample = s.ok ? { ok: true, n: s.n, columns: s.columns, rows: s.rows } : { ok: false, error: s.error, columns: [] };

  // 坐标：只有 spatial 才强制要求；其它方案留空即可
  if (this.form.scheme === 'spatial') {
    const x = inspectMatrix(this.form.coordinatesStr, c.ok ? c.n : null);
    this.v.coords = x.ok
      ? (x.p === 2 ? { ok: true, n: x.n, p: x.p } : { ok: false, n: x.n, error: `坐标需要 2 列（x,y），当前 ${x.p} 列` })
      : { ok: false, n: 0, error: x.error };
  } else {
    const t = this.form.coordinatesStr.trim();
    this.v.coords = t
      ? { ok: !!inspectMatrix(t).ok, n: inspectMatrix(t).n || 0, error: inspectMatrix(t).ok ? '' : '坐标 JSON 解析失败（当前方案不需要坐标，可清空）' }
      : { ok: true, n: 0 };
  }

  const terms = (this.form.formula || '').split('+').map((x) => x.trim()).filter(Boolean);
  this.v.formula = !terms.length
    ? { ok: false, msg: '公式至少需要一个因子' }
    : this.v.sample.ok && !terms.every((t) => this.v.sample.columns.includes(t))
      ? { ok: false, msg: `公式里的变量不在样本表：${terms.filter((t) => !this.v.sample.columns.includes(t)).join(', ')}` }
      : { ok: true, msg: `✓ 术语：${terms.join(' + ')}（首项为检验对象）` };

  this.v.scheme = this.form.scheme === 'stratified' && !this.form.strata
    ? { ok: false, msg: 'stratified 方案需要选择分层变量' }
    : this.form.scheme === 'spatial' && !(this.v.coords.ok && this.v.coords.n)
      ? { ok: false, msg: 'spatial 方案需要每个样本的 (x,y) 坐标' }
      : this.form.scheme === 'stratified' && this.v.sample.ok && !this.v.sample.columns.includes(this.form.strata)
        ? { ok: false, msg: `分层变量 ${this.form.strata} 不在样本表里` }
        : { ok: true, msg: '' };

  return [this.v.community.ok, this.v.sample.ok, this.v.coords.ok, this.v.formula.ok, this.v.scheme.ok];
},

