import fs from 'node:fs';

const f = 'frontend/src/views/r-analysis/Nonrandom_PERMANOVA.vue';
let s = fs.readFileSync(f, 'utf8');
const log = [];
const fail = [];
const sub = (from, to, label, all = true) => {
  if (!s.includes(from)) { fail.push(label + '（未匹配）'); return; }
  s = all ? s.split(from).join(to) : s.replace(from, to);
  log.push(label);
};

// 1) 模板/计算属性里的影子状态 v.* 全部改为 checks.*
s = s.replace(/\bthis\.v\.(community|sample|coords|formula|scheme)/g, 'this.checks.$1');
s = s.replace(/([{ (\[])(v)\.(community|sample|coords|formula|scheme)/g, '$1checks.$3');
log.push('v.* -> checks.*');

// 2) 不再需要手动触发校验（checks 是响应式的）
sub(' @change="validate"', '');
log.push('移除 @change="validate"');

// 3) 删掉 data 里的 v 影子状态
sub(`      v: {
        community: { ok: false },
        sample: { ok: false },
        coords: { ok: true, n: 0 },
        formula: { ok: true, msg: '公式待校验' },
        scheme: { ok: false, msg: '' }
      },
`, '', '删除 data.v');

// 4) 删掉 validate()，改成 checks 计算属性
sub(`    /** checkAll 的有副作用版本：把状态写回 this.v 供模板渲染 */
    validate() {
      this.v = this.checkAll();
      return Object.values(this.v).every((x) => x.ok);
    },

`, '', '删除 validate()');

sub(`    sampleColumns() {
      return this.checks.sample.columns || [];
    },`,
`    /** 五项输入状态：唯一来源，模板与 canRun 都读它（原来另有 this.v，程序填表时显示会滞后） */
    checks() {
      return this.checkAll();
    },
    sampleColumns() {
      return this.checks.sample.columns || [];
    },`, '新增 computed.checks');

sub('      this.validate();\n', '', 'loadNrTemplate 去掉 validate 调用', false);
s = s.replace(/      this\.validate\(\);\n/, '');
s = s.replace(/      if \(!this\.validate\(\)\) \{/, '      if (!this.canRun) {');
log.push('runAnalysis 用 canRun 把关');

fs.writeFileSync(f + '.tmp', s);
fs.renameSync(f + '.tmp', f);
console.log(log.join('\n'));
if (fail.length) { console.error('问题：\n  ' + fail.join('\n  ')); process.exit(1); }

