/**
 * Excel / CSV 读写（R 分析界面共用）
 * ---------------------------------------------------------------
 * 只放"和数据形状有关"的纯函数，不认得任何具体模块，方便三个（将来五个）分析界面共用：
 *   1) 模板：下载一个填好的样例工作簿
 *   2) 导入：把工作簿解析成引擎要的形态，并按样本 ID 对齐
 *   3) 导出：把结果写成多 sheet 工作簿 / 图表 PNG
 *
 * 为什么单独成文件：PERMANOVA.vue 里这三件事原来是写在视图内的 ~400 行，
 * 换个模块就得整段复制；一旦某个 sheet 名改了（比如"样本数据"→"样本信息"），
 * 两边就会各改各的。这里集中，视图只负责排版。
 *
 * 约定（和 r-scripts/nonrandom_permanova.R 的入参一致）：
 *   communityData: 样本 × 物种的数值矩阵（第一列样本 ID，其余列为物种/OTU 丰度）
 *   sampleData:    行对象数组，第一列样本 ID，其余列为分组变量（必须都是因子）
 *   coordinates:   样本 × (x, y[, z])，第一列样本 ID
 */

// 表头/工作表名的常见写法。用户手上的表多半是从别处导出的，中英文、大小写、
// 带不带空格都可能，匹配不上就整表拒绝太不友好，但静默猜列更糟——所以只认这张表，
// 认不出来时明确报"缺哪一列"。
export const SHEET_ALIASES = {
  community: ['物种矩阵', '群落矩阵', '丰度矩阵', 'OTU表', '物种', 'community', 'otu', 'abundance'],
  sample: ['样本信息', '样本数据', '分组信息', '样本表', 'metadata', 'sample', 'samples', 'grouping'],
  coordinate: ['坐标', '空间坐标', '经纬度', 'coordinate', 'coordinates', 'xy', 'space'],
  distance: ['距离矩阵', '相异度矩阵', 'distance', 'dissimilarity', 'bray']
};

const SAMPLE_ID_KEYS = ['样本', '样本id', '样品', '样本编号', 'id', 'sample', 'sampleid', 'samples', 'row', '站点'];

const norm = (s) => String(s ?? '').trim().toLowerCase().replace(/[\s_\-]+/g, '');
const isBlank = (s) => !String(s ?? '').trim();

/** 第一列是不是样本 ID 列（有的表第一列是行名，Excel 里表头为空） */
function detectIdColumn(header) {
  const cells = header.map(norm);
  const hit = cells.findIndex((c) => SAMPLE_ID_KEYS.includes(c));
  if (hit >= 0) return hit;
  // 表头第一格为空、其余像变量名 -> 认定第一列是行名（aoa_to_sheet 写出的表就是这样）
  if (isBlank(header[0]) && header.slice(1).some((h) => !isBlank(h))) return 0;
  return 0;
}

/** 按别名表在工作簿里找一张表；返回 { name, aoa } 或 null */
export function findSheet(sheets, kind) {
  const aliases = (SHEET_ALIASES[kind] || []).map(norm);
  const names = Object.keys(sheets);
  for (const n of names) {
    const k = norm(n);
    if (aliases.includes(k)) return { name: n, aoa: sheets[n] };
  }
  for (const n of names) {
    const k = norm(n);
    if (aliases.some((a) => k.includes(a) || a.includes(k))) return { name: n, aoa: sheets[n] };
  }
  return null;
}

/**
 * 物种矩阵 sheet -> { ids: string[], matrix: number[][], species: string[] }
 * 允许表头第一格为空（行名式）；非数值单元格报错而不是当 0。
 */
export function parseCommunitySheet(aoa) {
  if (!Array.isArray(aoa) || aoa.length < 2) return { ok: false, error: '物种矩阵表至少要有表头和一行数据' };
  const header = aoa[0];
  const idCol = detectIdColumn(header);
  const species = header.filter((_, i) => i !== idCol && !isBlank(_)).map(String);
  const speciesIdx = header.map((h, i) => i).filter((i) => i !== idCol && !isBlank(header[i]));
  const ids = [];
  const matrix = [];
  for (let r = 1; r < aoa.length; r++) {
    const row = aoa[r] || [];
    if (!row.some((c) => !isBlank(c))) continue;              // 跳过完全空行
    const id = String(row[idCol] ?? '').trim() || `S${r}`;
    const vals = speciesIdx.map((i) => row[i]);
    const bad = vals.findIndex((v) => v === '' || v === null || v === undefined || !Number.isFinite(Number(v)));
    if (bad >= 0) {
      return { ok: false, error: `物种矩阵第 ${r + 1} 行第 ${bad + 1} 个物种不是数值（"${String(vals[bad])}"）` };
    }
    ids.push(id);
    matrix.push(vals.map(Number));
  }
  if (!ids.length) return { ok: false, error: '物种矩阵没有有效数据行' };
  if (new Set(ids).size !== ids.length) return { ok: false, error: '物种矩阵里有重复样本 ID' };
  return { ok: true, ids, matrix, species };
}

/** 样本信息 sheet -> { ids: string[], rows: object[], columns: string[] }（rows 不含样本 ID 列） */
export function parseSampleSheet(aoa) {
  if (!Array.isArray(aoa) || aoa.length < 2) return { ok: false, error: '样本信息表至少要有表头和一行数据' };
  const header = aoa[0];
  const idCol = detectIdColumn(header);
  const cols = header.map((h, i) => ({ h: String(isBlank(h) ? `col${i}` : h).trim(), i })).filter((c) => c.i !== idCol);
  if (!cols.length) return { ok: false, error: '样本信息表里除了样本 ID 没有其它列（至少要有一个分组变量）' };
  const ids = [];
  const rows = [];
  for (let r = 1; r < aoa.length; r++) {
    const row = aoa[r] || [];
    if (!row.some((c) => !isBlank(c))) continue;
    ids.push(String(row[idCol] ?? '').trim());
    const obj = {};
    for (const c of cols) {
      const v = row[c.i];
      // 全部转成字符串：R 侧要求分组变量是因子，数值型会被 jsonlite 当连续变量然后拒绝
      obj[c.h] = v === null || v === undefined || v === '' ? '' : String(v).trim();
    }
    rows.push(obj);
  }
  if (!ids.length) return { ok: false, error: '样本信息表没有有效数据行' };
  if (new Set(ids).size !== ids.length) return { ok: false, error: '样本信息表里有重复样本 ID' };
  return { ok: true, ids, rows, columns: cols.map((c) => c.h) };
}

/** 坐标 sheet -> { ids, coords: number[][] }（第 2~3 列为 x,y；多出的列忽略） */
export function parseCoordinateSheet(aoa) {
  const p = parseSampleSheet(aoa);
  if (!p.ok) return p;
  if (p.columns.length < 2) return { ok: false, error: '坐标表需要 x、y 两列' };
  const [cx, cy] = p.columns;
  const bad = p.rows.findIndex((r) => !Number.isFinite(Number(r[cx])) || !Number.isFinite(Number(r[cy])));
  if (bad >= 0) return { ok: false, error: `坐标表第 ${bad + 2} 行的 ${cx}/${cy} 不是数值` };
  return {
    ok: true,
    ids: p.ids,
    coords: p.rows.map((r) => [Number(r[cx]), Number(r[cy])])
  };
}

/**
 * 按样本 ID 对齐群落矩阵与样本信息（顺序不同就重排，缺样本直接拒绝）
 * 不静默按行号对齐：Excel 里排序一变，行号对齐会把分组整体错位，结果看着完全正常但毫无意义。
 */
export function alignBySampleId(comm, sample) {
  const idx = new Map(sample.ids.map((id, i) => [id, i]));
  const missing = comm.ids.filter((id) => !idx.has(id));
  if (missing.length) {
    return { ok: false, error: `样本信息里缺少这些样本：${missing.slice(0, 5).join(', ')}${missing.length > 5 ? ` 等 ${missing.length} 个` : ''}` };
  }
  const extra = sample.ids.filter((id) => !comm.ids.includes(id));
  const rows = comm.ids.map((id) => sample.rows[idx.get(id)]);
  return { ok: true, rows, extra };
}

/** 距离矩阵 sheet（方阵，对称性只警告不拒绝——用户可能只填上三角） */
export function parseDistanceSheet(aoa) {
  if (!Array.isArray(aoa) || aoa.length < 3) return { ok: false, error: '距离矩阵表太小' };
  const header = aoa[0];
  const ids = header.slice(1).map((h) => String(h ?? '').trim());
  const rows = [];
  for (let r = 1; r < aoa.length; r++) {
    const row = aoa[r] || [];
    if (!row.some((c) => !isBlank(c))) continue;
    if (rows.length >= ids.length) return { ok: false, error: '距离矩阵不是方阵：数据行数超过列数' };
    const vals = ids.map((_, i) => Number((row || [])[i + 1]));
    const bad = vals.findIndex((v) => !Number.isFinite(v));
    if (bad >= 0) return { ok: false, error: `距离矩阵第 ${r + 1} 行第 ${bad + 1} 列不是数值` };
    rows.push(vals);
  }
  if (rows.length !== ids.length) return { ok: false, error: `距离矩阵不是方阵：${ids.length} 列但 ${rows.length} 行` };
  let symmetric = true;
  for (let i = 0; i < rows.length && symmetric; i++) {
    for (let j = 0; j < i; j++) if (Math.abs(rows[i][j] - rows[j][i]) > 1e-9) { symmetric = false; break; }
  }
  return { ok: true, ids, matrix: rows, symmetric };
}

// ---------------------------------------------------------------- 写：模板与导出

/** aoa -> sheet；XLSX 由调用方注入，避免这里静态 import 影响 Node 测试 */
export function sheetFromAoa(XLSX, aoa, colWidths = null) {
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  if (colWidths) ws['!cols'] = colWidths.map((w) => ({ wch: w }));
  return ws;
}

export function writeWorkbook(XLSX, sheets, filename) {
  const wb = XLSX.utils.book_new();
  for (const [name, aoa] of sheets) {
    XLSX.utils.book_append_sheet(wb, sheetFromAoa(XLSX, aoa), name.slice(0, 31));
  }
  XLSX.writeFile(wb, filename);
}

/**
 * 一个可直接填写的示例工作簿：物种矩阵 / 样本信息 / 坐标 / 说明
 * 数值取自 6 样本 × 8 物种的小设计，用户照着换成自己的即可。
 */
export function buildTemplateSheets() {
  const species = ['Bacteroides', 'Prevotella', 'Faecalibacterium', 'Ruminococcus', 'Akkermansia', 'Bifidobacterium', 'Escherichia', 'Lactobacillus'];
  const ids = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6'];
  const abund = [
    [42, 18, 30, 5, 2, 11, 7, 3],
    [38, 22, 26, 8, 1, 9, 5, 4],
    [12, 9, 15, 28, 14, 3, 2, 1],
    [15, 11, 12, 31, 10, 4, 3, 2],
    [9, 7, 18, 25, 16, 2, 1, 1],
    [45, 20, 28, 4, 3, 12, 6, 5]
  ];
  const community = [['样本', ...species], ...ids.map((id, i) => [id, ...abund[i]])];
  const sample = [
    ['样本', 'group', 'strata'],
    ['S1', 'Case', 'B1'], ['S2', 'Case', 'B1'], ['S3', 'Case', 'B2'],
    ['S4', 'Control', 'B2'], ['S5', 'Control', 'B3'], ['S6', 'Control', 'B3']
  ];
  const coord = [
    ['样本', 'x', 'y'],
    ['S1', 0, 0], ['S2', 1.2, 0.6], ['S3', 20, 4], ['S4', 21.5, 3.2], ['S5', 40, 12], ['S6', 41, 12.6]
  ];
  const notes = [
    ['Non-random PERMANOVA 数据模板'],
    [''],
    ['📄 物种矩阵（必需）：'],
    ['   第一列样本 ID，其余每列一个物种/OTU 的丰度（原始读数即可，无需先标准化）'],
    ['   行 = 样本，列 = 物种'],
    [''],
    ['📋 样本信息（必需）：'],
    ['   第一列样本 ID（需与物种矩阵一致，顺序可以不同，导入时按 ID 对齐）'],
    ['   group 是待检验的分组；strata 是分层变量（受限置换只在 strata 内部交换标签）'],
    ['   ⚠️ 本模块只接受因子（分类）变量；pH、年龄这类连续变量请先分箱'],
    [''],
    ['📍 坐标（可选）：'],
    ['   只有选择「空间受限置换」时才需要；第一列样本 ID，另两列 x/y'],
    [''],
    ['导入后请核对预览，再点「填入表单」']
  ];
  return [
    ['物种矩阵', community],
    ['样本信息', sample],
    ['坐标', coord],
    ['填写说明', notes]
  ];
}

/** 读文件 -> { sheets: { 名: aoa } }；CSV 走单 sheet */
export async function readWorkbook(file) {
  const XLSX = await import('xlsx');
  const buf = await file.arrayBuffer();
  const wb = XLSX.read(buf, { type: 'array' });
  const sheets = {};
  for (const name of wb.SheetNames) {
    sheets[name] = XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, blankrows: false, defval: '' });
  }
  return sheets;
}

#!/usr/bin/env node
/**
 * sheetIo.js（Excel/CSV 导入导出底层）回归
 * ---------------------------------------------------------------
 * 关键做法：真把模板工作簿写出来、再用 readWorkbook 读回来解析，
 * 而不是只测纯函数——"下载模板 -> 用户填 -> 上传"这条链的两端必须是同一套约定。
 *
 * 用法：node r-scripts/tools/test_sheet_io.mjs
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '../..');
const { default: XLSX } = await import(path.join(ROOT, 'frontend/node_modules/xlsx/xlsx.mjs'));
const mod = await import(path.join(ROOT, 'frontend/src/utils/sheetIo.js'));
const {
  SHEET_ALIASES, findSheet, parseCommunitySheet, parseSampleSheet, parseCoordinateSheet,
  parseDistanceSheet, alignBySampleId, buildTemplateSheets, writeWorkbook, readWorkbook
} = mod;

let pass = 0;
const fails = [];
const t = (name, cond, extra = '') => {
  if (cond) { pass++; console.log(`  ✓ ${name}`); }
  else { fails.push(name + (extra ? ` —— ${extra}` : '')); console.log(`  ✗ ${name}${extra ? `\n      ${extra}` : ''}`); }
};
const aoaToBook = (sheets) => {
  const wb = XLSX.utils.book_new();
  for (const [n, aoa] of sheets) XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), n);
  return wb;
};
const bookToFile = (wb, name = 'x.xlsx') => {
  const buf = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
  return new File([buf], name);
};

console.log('\n[1] 模板工作簿 -> 读回 -> 解析（整链）');
const tpl = buildTemplateSheets();
t('模板含 4 张表', tpl.length === 4, tpl.map((x) => x[0]).join(','));
for (const need of ['物种矩阵', '样本信息', '坐标']) {
  t(`模板里有「${need}」表`, tpl.some(([n]) => n === need));
}
const tplFile = bookToFile(aoaToBook(tpl));
const back = await readWorkbook(tplFile);
t('readWorkbook 认全部 sheet', Object.keys(back).length === 4, Object.keys(back).join(','));
const comm = findSheet(back, 'community');
const samp = findSheet(back, 'sample');
const coord = findSheet(back, 'coordinate');
t('按别名找到物种矩阵表', !!comm && comm.name === '物种矩阵', comm && comm.name);
const pc = parseCommunitySheet(comm.aoa);
t('物种矩阵解析成功', pc.ok === true, pc.error);
t('6 样本 × 8 物种', pc.ids.length === 6 && pc.matrix.every((r) => r.length === 8), `${pc.ids.length}×${(pc.matrix[0] || []).length}`);
t('物种名取自表头', pc.species[0] === 'Bacteroides' && pc.species.length === 8, (pc.species || []).join(','));
t('数值类型正确', pc.matrix[0][0] === 42 && typeof pc.matrix[0][0] === 'number');
const ps = parseSampleSheet(samp.aoa);
t('样本信息解析成功', ps.ok === true, ps.error);
t('样本信息列为 group/strata', ps.columns.join(',') === 'group,strata', ps.columns.join(','));
const pco = parseCoordinateSheet(coord.aoa);
t('坐标解析成功', pco.ok === true && pco.coords.length === 6, pco.error);
const al = alignBySampleId(pc, ps);
t('按 ID 对齐成功', al.ok === true, al.error);
t('对齐后行数与群落矩阵一致', al.rows.length === pc.ids.length);
t('分组跟着样本走（S1=Case, S6=Control）', al.rows[0].group === 'Case' && al.rows[5].group === 'Control',
  al.rows.map((r) => r.group).join(','));

console.log('\n[2] 下载模板再上传，得到的必须就是模板里那份数据');
writeWorkbook(XLSX, tpl, path.join(os.tmpdir(), 'nr-tpl.xlsx'));
const diskFile = new File([fs.readFileSync(path.join(os.tmpdir(), 'nr-tpl.xlsx'))], 'nr-tpl.xlsx');
const back2 = await readWorkbook(diskFile);
t('writeWorkbook 落盘可读', Object.keys(back2).length === 4);
t('两次解析结果一致（可复现）',
  JSON.stringify(parseCommunitySheet(findSheet(back2, 'community').aoa)) === JSON.stringify(pc));

console.log('\n[3] 真实脏数据：表名/表头写法五花八门');
for (const [kind, names] of Object.entries(SHEET_ALIASES)) {
  for (const n of names.slice(0, 3)) {
    const sheets = kind === 'community'
      ? { [n]: [['样本', 'sp1'], ['A', 1], ['B', 2]] }
      : kind === 'sample'
        ? { [n]: [['样本', 'group'], ['A', 'X'], ['B', 'Y']] }
        : { [n]: [['样本', 'x', 'y'], ['A', 0, 0], ['B', 1, 1]] };
    const hit = findSheet(sheets, kind);
    t(`别名「${n}」能被认作 ${kind} 表`, !!hit && hit.name === n, hit ? '' : '未命中');
  }
}
t('无关表名不误命中', findSheet({ 随便写的: [[1]] }, 'community') === null);

console.log('\n[4] 顺序错位：必须按 ID 重排，不能按行号');
const shuffledComm = { ok: true, ids: ['S3', 'S1', 'S2'], matrix: [[1], [2], [3]] };
const shuffledSample = { ok: true, ids: ['S1', 'S2', 'S3'], rows: [{ g: 'a' }, { g: 'b' }, { g: 'c' }], columns: ['g'] };
const fixed = alignBySampleId(shuffledComm, shuffledSample);
t('乱序样本被重排（S3->c, S1->a, S2->b）',
  fixed.rows.map((r) => r.g).join(',') === 'c,a,b', fixed.rows.map((r) => r.g).join(','));
const lost = alignBySampleId({ ok: true, ids: ['S1', 'S9'], matrix: [[1], [2]] }, shuffledSample);
t('缺样本时明确拒绝并列出是谁', !lost.ok && /S9/.test(lost.error), lost.error);
const surplus = alignBySampleId({ ok: true, ids: ['S1'], matrix: [[1]] }, shuffledSample);
t('多余样本不阻断，但报出来', surplus.ok === true && surplus.extra.length === 2, JSON.stringify(surplus.extra));

console.log('\n[5] 该拒绝的必须拒绝（不能悄悄补 0 或按行号猜）');
t('丰度非数值 -> 报错并定位', !parseCommunitySheet([['样本', 'a', 'b'], ['S1', 1, 'NA']]).ok);
const badCell = parseCommunitySheet([['样本', 'a', 'b'], ['S1', 1, 'xx'], ['S2', 2, 3]]);
t('报错包含行列位置', !badCell.ok && /第 2 行/.test(badCell.error) && /第 2 个物种/.test(badCell.error), badCell.error);
t('重复样本 ID -> 报错', !parseCommunitySheet([['样本', 'a'], ['S1', 1], ['S1', 2]]).ok);
t('只有表头 -> 报错', !parseCommunitySheet([['样本', 'a']]).ok);
t('空行被跳过', parseCommunitySheet([['样本', 'a'], ['S1', 1], ['', ''], ['S2', 2]]).ids.length === 2);
t('行名式表头（第一格空）也认', parseCommunitySheet([['', 'a', 'b'], ['S1', 1, 2]]).ok === true);
t('行名式表头取到列名', parseCommunitySheet([['', 'a', 'b'], ['S1', 1, 2]]).species.join(',') === 'a,b');
const numericGroup = parseSampleSheet([['样本', 'group'], ['S1', 1], ['S2', 2]]);
t('数值型分组转成字符串（否则 R 会当连续变量拒掉）',
  numericGroup.ok === true && numericGroup.rows[0].group === '1' && typeof numericGroup.rows[0].group === 'string',
  JSON.stringify(numericGroup.rows[0]));
t('样本信息只有 ID 列 -> 报错', !parseSampleSheet([['样本'], ['S1']]).ok);
t('坐标不足两列 -> 报错', !parseCoordinateSheet([['样本', 'x'], ['S1', 1]]).ok);
t('坐标非数值 -> 报错', !parseCoordinateSheet([['样本', 'x', 'y'], ['S1', 1, '米']]).ok);
const nonsym = parseDistanceSheet([['', 'A', 'B'], ['A', 0, 0.4], ['B', 0.9, 0]]);
t('距离矩阵不对称 -> symmetric=false', nonsym.ok === true && nonsym.symmetric === false);
const sym = parseDistanceSheet([['', 'A', 'B'], ['A', 0, 0.4], ['B', 0.4, 0]]);
t('对称距离矩阵 -> symmetric=true', sym.ok === true && sym.symmetric === true);
t('距离矩阵非方阵 -> 报错', !parseDistanceSheet([['', 'A', 'B'], ['A', 0, 0.1]]).ok);
t('CSV 单表也能读', await (async () => {
  const f = new File([new Blob(['样本,group\nS1,A\nS2,B\n'])], 'a.csv', { type: 'text/csv' });
  const s = await readWorkbook(f);
  const only = Object.values(s)[0];
  return parseSampleSheet(only).ok === true;
})());

console.log(`\n──────── ${pass} 通过 / ${fails.length} 失败 ────────`);
if (fails.length) { fails.forEach((f) => console.log('  - ' + f)); process.exit(1); }

