fs.writeFileSync(V, s);
console.log('视图方法区已换成 spec 驱动');
for (const k of ['importPreview', 'uploadFileList', 'alignBySampleId', 'buildTemplateSheets', 'NR_PREVIEW_TABS', 'exportSheets']) {
  console.log('  残留 ' + k + ' =', (s.match(new RegExp(k, 'g')) || []).length);
}

// ---------------------------------------------------------- 模板 / 导入 / 导出
