},

/** 解析交给 sheetIo.mapWorkbook 按 spec 跑：缺表指名、按主表 ID 对齐、形状隐患出警告 */
async handleFileChange(raw) {
  this.importTabs = null;
  this.importError = '';
  this.importWarnings = [];
  this.imported = null;
  if (!raw) return;
  try {
    const sheets = await readWorkbook(raw);
