    this.showExportDialog = false;
    this.notify('success', `已导出 ${jobs.length} 项`);
  } catch (e) {
    this.exportError = '导出失败：' + (e.message || e);
  }
},

/** 组装 spec 里 build()/data() 需要的上下文：全是纯数据，所以导出内容能在 Node 里断言 */
exportCtx(chartTabName) {
