/**
 * 模型公式表：整张表里找到第一个含“~”的单元格就当公式。
 * 公式必须含因变量（Y ~ …），只写右边是错的；这里不猜。
 */
export function parseFormulaSheet(aoa) {
  if (!Array.isArray(aoa) || !aoa.length) return { ok: false, error: '模型公式表是空的' };
  let formula = '';
  for (const row of aoa) {
    for (const cell of row || []) {
      const s = String(cell ?? '').trim();
      if (s.includes('~')) { formula = s; break; }
    }
    if (formula) break;
  }
  if (!formula) return { ok: false, error: '模型公式表里没找到含“~”的公式（如 Y ~ group）' };
  if (!formula.split('~')[0].trim()) {
    return { ok: false, error: `模型公式缺因变量：「${formula}」应写成 Y ~ …` };
  }
  return { ok: true, formula };
}

