// 一次性 codemod：把 PERMANOVA.vue 的导入/导出换成三层架构（跑完即删）
import fs from 'node:fs';

const F = 'frontend/src/views/r-analysis/PERMANOVA.vue';
let src = fs.readFileSync(F, 'utf8');
const lines = () => src.split('\n');

const findLine = (re, from = 0) => {
  const ls = lines();
  for (let i = from; i < ls.length; i++) if (re.test(ls[i])) return i;
  throw new Error('找不到锚点 ' + re);
};
/** 替换 [startRe, endRe)（endRe 那一行保留） */
function replaceRange(startRe, endRe, text, opts = {}) {
  const s = findLine(startRe, opts.from || 0);
  const e = findLine(endRe, s + 1);
  const ls = lines();
  ls.splice(s, e - s, ...text.split('\n'));
  src = ls.join('\n');
  return s;
}

// 1) imports
src = src.replace(
  "import {\n  checkR,\n  runPERMANOVA\n} from '@/api/r';",
  `import {
  checkR,
  runPERMANOVA
} from '@/api/r';

import ToolbarActions from '@/components/r-analysis/ToolbarActions.vue';
import ImportDialog from '@/components/r-analysis/ImportDialog.vue';
import ExportDialog from '@/components/r-analysis/ExportDialog.vue';
import {
  readWorkbook,
  mapWorkbook,
  previewFromFields,
  writeWorkbook
} from '@/utils/sheetIo';
import {
  PM_IMPORT_SHEETS,
  PM_EXPORT_OPTIONS,
  pmToFormPatch,
  pmTemplateSheets,
  planExport
} from '@/utils/permanovaSheetSpec';`);

// 2) components 注册
src = src.replace(/components: \{\n/, `components: {\n  ToolbarActions,\n  ImportDialog,\n  ExportDialog,\n`);

// 3) 侧边工具栏
replaceRange(/^      <div class="toolbar-content">$/, /^    <\/div>\n$/, '', {}) /* placeholder */);
{
  const ls = lines();
  const s = findLine(/^      <div class="toolbar-content">$/);
  // toolbar-content 结束 = 第一个单独成行的 "      </div>" 之后紧跟 "    </div>"
  let e = s;
  while (!(ls[e].trim() === '</div>' && ls[e + 1] && ls[e + 1].trim() === '</div>')) e++;
  ls.splice(s, e - s + 2, `      <ToolbarActions\n        :has-result="!!analysisResult" :show-input="true"\n        @template="downloadTemplate" @import="openImport" @export="openExport" @input="downloadInput"\n      />`);
  src = ls.join('\n');
}

// 4) 导入对话框
replaceRange(/^  <el-dialog v-model="showImportDialog"/, /^  <\/el-dialog>\n\n  <!-- 导出结果对话框 -->$/, `  <ImportDialog v-model="showImportDialog" :sheets="importSheets" :tabs="importTabs"
    :error="importError" :warnings="importWarnings" @file-change="handleFileChange" @apply="applyImport" />

  <!-- 导出结果对话框 -->`);

// 5) 导出对话框
replaceRange(/^  <el-dialog v-model="showExportDialog"/, /^  <\/el-dialog>\n\n  <!-- 事后检验配置对话框 -->$/, `  <ExportDialog v-model="showExportDialog" :options="exportOptions2" :selected="exportOptions"
    :error="exportError" @update:selected="(v) => (exportOptions = v)" @confirm="confirmExport" />

  <!-- 事后检验配置对话框 -->`);

// 6) data() 里的导入状态
src = src.replace(
  /      showImportDialog: false,\n      uploadFileList: \[.*?\],.*?\n      importPreview: null,\n      importPreviewActiveTab: 'distance',\n      importError: '',\n      importedData: null,\n/,
  `      showImportDialog: false,
      importTabs: null,
      importFields: null,
      importIds: null,
      importWarnings: [],
      importError: '',
`);

// 7) 死掉的两个校验器（同名定义有两处，后者覆盖前者）
{
  const s = findLine(/^    validateDistanceMatrix\(\) \{$/);
  const e = findLine(/^    async runPERMANOVA\(\) \{$/);
  const ls = lines();
  ls.splice(s, e - s, '    // validateDistanceMatrix / validateSampleData 原先在这里还各有一份定义，\n    // 同一个 methods 对象里同名后者覆盖前者，那份从来没被执行过，已删。\n    // 生效的定义在文件后面（搜索名字只应命中一处）。\n');
  src = ls.join('\n');
}

// 8) 导入/导出/模板这一整块方法重写
{
  const s = findLine(/^    async handleFileChange\(file\) \{$/);
  const e = findLine(/^    loadTemplate\(templateName\) \{$/);
  const ls = lines();
  ls.splice(s, e - s, NEW_METHODS);
  src = ls.join('\n');
}

// 9) runPERMANOVA 里内联的 params 组装换成 buildRunParams
{
  const ls = lines();
  const s = findLine(/^        const params = \{$/);
  let e = s;
  while (!/^\s*\};$/.test(ls[e])) e++;
  ls.splice(s, e - s + 1, '        const params = this.buildRunParams();');
  src = ls.join('\n');
}

// 10) 残留引用检查
