export function findSheet(sheets, kind, names) {
  const aliases = (names || SHEET_ALIASES[kind] || []).map(norm);
  const names = Object.keys(sheets);
  for (const n of names) {
    const k = norm(n);
    if (aliases.includes(k)) return { name: n, aoa: sheets[n] };
  }
  for (const n of names) {
    const k = norm(n);
    if (aliases.some((a) => k.includes(a) || a.includes(k))) return { name: n, aoa: sheets[n] };
  }
  return null;
}

